export enum SlideLayout {
  TITLE = 'title',
  BULLET_POINTS = 'bullet_points',
  TWO_COLUMN = 'two_column',
  QUOTE = 'quote',
  SECTION_HEADER = 'section_header'
}

export interface SlideData {
  title: string;
  subtitle?: string;
  content: string[];
  layout: SlideLayout;
  imageKeyword?: string; // For searching/generating placeholder images
  notes?: string;
}

export interface Presentation {
  topic: string;
  slides: SlideData[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { SlideData, SlideLayout } from "../types";

// Note: In a real production app, this would be a secure backend endpoint.
const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY is not defined in the environment.");
  }
  return new GoogleGenAI({ apiKey });
};

export const generatePresentationContent = async (topic: string): Promise<SlideData[]> => {
  const ai = getClient();

  const prompt = `Create a professional presentation about: "${topic}". 
  Generate 5 to 7 slides. 
  Ensure variety in layouts. 
  For 'imageKeyword', provide a short, descriptive search term for a stock photo related to the slide content.`;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash",
    contents: prompt,
    config: {
      systemInstruction: "You are a world-class presentation designer and storyteller. You create engaging, structured slide decks.",
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            subtitle: { type: Type.STRING },
            content: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING } 
            },
            layout: { 
              type: Type.STRING, 
              enum: [
                "title", 
                "bullet_points", 
                "two_column", 
                "quote", 
                "section_header"
              ] 
            },
            imageKeyword: { type: Type.STRING },
            notes: { type: Type.STRING }
          },
          required: ["title", "content", "layout"]
        }
      }
    }
  });

  if (response.text) {
    try {
      return JSON.parse(response.text) as SlideData[];
    } catch (e) {
      console.error("Failed to parse Gemini response", e);
      throw new Error("Failed to generate valid presentation data.");
    }
  }

  throw new Error("No content generated.");
};

import React, { useEffect, useRef } from 'react';

const StarBackground: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let stars: { x: number; y: number; size: number; speed: number; opacity: number }[] = [];

    const resizeCanvas = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      initStars();
    };

    const initStars = () => {
      stars = [];
      const starCount = Math.floor((window.innerWidth * window.innerHeight) / 4000); // Density
      for (let i = 0; i < starCount; i++) {
        stars.push({
          x: Math.random() * canvas.width,
          y: Math.random() * canvas.height,
          size: Math.random() * 2,
          speed: Math.random() * 0.2 + 0.05,
          opacity: Math.random()
        });
      }
    };

    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Draw background gradient "fog"
      const gradient = ctx.createRadialGradient(
        canvas.width / 2, canvas.height / 2, 0,
        canvas.width / 2, canvas.height / 2, canvas.width
      );
      gradient.addColorStop(0, '#0f172a'); // Slate 900
      gradient.addColorStop(1, '#020617'); // Slate 950
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = 'white';
      stars.forEach((star) => {
        ctx.globalAlpha = star.opacity;
        ctx.beginPath();
        ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2);
        ctx.fill();

        // Move star
        star.y -= star.speed;

        // Reset if out of bounds
        if (star.y < 0) {
          star.y = canvas.height;
          star.x = Math.random() * canvas.width;
        }
      });
      ctx.globalAlpha = 1.0;

      // Draw faint grid lines for that "tech" feel
      ctx.strokeStyle = 'rgba(56, 189, 248, 0.03)';
      ctx.lineWidth = 1;
      const gridSize = 150;

      // Vertical lines
      for(let x = 0; x <= canvas.width; x += gridSize) {
         ctx.beginPath();
         ctx.moveTo(x, 0);
         ctx.lineTo(x, canvas.height);
         ctx.stroke();
      }

      animationFrameId = requestAnimationFrame(draw);
    };

    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();
    draw();

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return <canvas ref={canvasRef} className="fixed inset-0 z-0 pointer-events-none" />;
};

export default StarBackground;

import React from 'react';
import { SlideData, SlideLayout } from '../types';
import { Quote, List, Layout, Image as ImageIcon } from 'lucide-react';

interface SlideRendererProps {
