import React, { useState } from 'react';
import StarBackground from './components/StarBackground';
import { Sparkles, ArrowRight, X, ChevronLeft, ChevronRight, Download, Share2, Play } from 'lucide-react';
import { generatePresentationContent } from './services/geminiService';
import { SlideData } from './types';
import SlideRenderer from './components/SlideRenderer';

// Predefined suggestion chips
const SUGGESTIONS = [
  "Future of AI",
  "Cybersecurity",
  "Sustainable Energy",
  "Digital Marketing Strategy"
];

function App() {
  const [query, setQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedSlides, setGeneratedSlides] = useState<SlideData[] | null>(null);
  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!query.trim()) return;

    setIsGenerating(true);
    setError(null);
    try {
      const slides = await generatePresentationContent(query);
      setGeneratedSlides(slides);
      setCurrentSlideIndex(0);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unexpected error occurred.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleGenerate();
  };

  // Reset to home
  const goHome = () => {
    setGeneratedSlides(null);
    setQuery('');
    setError(null);
  };

  // Navigation handlers
  const nextSlide = () => setCurrentSlideIndex(prev => Math.min(prev + 1, (generatedSlides?.length || 1) - 1));
  const prevSlide = () => setCurrentSlideIndex(prev => Math.max(prev - 1, 0));

  // --- VIEW: EDITOR / PRESENTATION ---
  if (generatedSlides) {
    return (
      <div className="min-h-screen bg-slate-950 text-white flex flex-col font-sans">
        {/* Header */}
        <header className="h-16 border-b border-slate-800 bg-slate-950 flex items-center justify-between px-6 z-20">
          <div className="flex items-center space-x-4 cursor-pointer" onClick={goHome}>
            <div className="w-8 h-8 rounded bg-gradient-to-br from-blue-600 to-indigo-600 flex items-center justify-center font-bold text-lg">O</div>
            <span className="font-bold tracking-tight text-lg">OrbitSlide <span className="text-blue-400">AI</span></span>
          </div>

          <div className="flex items-center space-x-3">
             <button className="flex items-center gap-2 px-4 py-2 text-sm text-slate-300 hover:text-white transition-colors">
               <Share2 size={16} /> Share
             </button>
             <button className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 rounded-md text-sm transition-colors border border-slate-700">
               <Download size={16} /> Export PDF
             </button>
             <button className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 rounded-md text-sm font-semibold transition-colors shadow-lg shadow-blue-900/20">
               <Play size={16} fill="currentColor" /> Present
             </button>
          </div>
        </header>

        {/* Main Content Area */}
        <main className="flex-1 flex overflow-hidden">
           {/* Sidebar Thumbnails */}
           <div className="w-64 border-r border-slate-800 bg-slate-900/50 flex flex-col overflow-y-auto p-4 space-y-4">
              <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">Slides</h3>
              {generatedSlides.map((slide, idx) => (
                <div 
                  key={idx}
                  onClick={() => setCurrentSlideIndex(idx)}
                  className={`cursor-pointer group relative aspect-video rounded-md border-2 transition-all duration-200 overflow-hidden ${
                    idx === currentSlideIndex 
                    ? 'border-blue-500 shadow-[0_0_15px_rgba(59,130,246,0.5)]' 
                    : 'border-slate-700 hover:border-slate-500 opacity-70 hover:opacity-100'
                  }`}
                >
                  <div className="absolute inset-0 bg-slate-800 flex items-center justify-center">
                    <span className="text-[10px] text-slate-400 px-2 text-center truncate w-full">{slide.title}</span>
                  </div>
                  <div className="absolute bottom-1 right-1 w-5 h-5 bg-black/50 rounded flex items-center justify-center text-[10px] text-white">
                    {idx + 1}
                  </div>
                </div>
              ))}
           </div>

           {/* Canvas */}
           <div className="flex-1 bg-slate-950 relative flex items-center justify-center p-8 lg:p-12">

              {/* Main Slide View */}
              <div className="w-full max-w-5xl aspect-video relative z-10 transition-all duration-500">
                <SlideRenderer slide={generatedSlides[currentSlideIndex]} />
              </div>

              {/* Navigation Arrows */}
              <button 
                onClick={prevSlide}
                disabled={currentSlideIndex === 0}
                className="absolute left-4 p-3 rounded-full bg-slate-800/80 hover:bg-blue-600 disabled:opacity-30 disabled:hover:bg-slate-800 transition-all text-white backdrop-blur-sm"
              >
                <ChevronLeft size={24} />
              </button>

              <button 
                onClick={nextSlide}
                disabled={currentSlideIndex === generatedSlides.length - 1}
                className="absolute right-4 p-3 rounded-full bg-slate-800/80 hover:bg-blue-600 disabled:opacity-30 disabled:hover:bg-slate-800 transition-all text-white backdrop-blur-sm"
              >
                <ChevronRight size={24} />
              </button>
           </div>
        </main>
      </div>
    );
  }

  // --- VIEW: HOME / HERO ---
  return (
    <div className="relative min-h-screen w-full overflow-hidden flex flex-col items-center justify-center">
      <StarBackground />

      {/* Branding - Top Left */}
      <div className="absolute top-8 left-8 z-10 flex flex-col">
        <span className="text-[10px] uppercase tracking-[0.2em] text-slate-400 font-bold mb-1">Presented by</span>
        <div className="flex items-center gap-2">
            <div className="h-6 w-1 bg-blue-500 rounded-full"></div>
            <span className="text-2xl font-black tracking-widest text-white">NEXZI</span>
        </div>
      </div>

      {/* Main Container */}
      <div className="relative z-10 flex flex-col items-center max-w-4xl w-full px-4 text-center">

        {/* Pill Badge */}
        <div className="mb-8 inline-flex items-center gap-2 px-4 py-1.5 rounded-full border border-blue-500/30 bg-blue-950/30 backdrop-blur-md shadow-[0_0_20px_rgba(59,130,246,0.3)] animate-float">
          <Sparkles className="w-4 h-4 text-blue-400" />
          <span className="text-sm font-semibold text-blue-100">OrbitSlide AI</span>
        </div>

        {/* Hero Text */}
        <h1 className="text-6xl md:text-8xl font-black tracking-tight leading-[1.1] mb-2">
          Roar into
        </h1>
        <h1 className="text-6xl md:text-8xl font-black tracking-tight leading-[1.1] mb-8 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 via-cyan-400 to-blue-500 glow-text">
          Greatness.
        </h1>

        <p className="max-w-2xl text-lg md:text-xl text-slate-300 font-light leading-relaxed mb-12 opacity-90">
          Unleash the power of AI to create professional slide decks instantly with OrbitSlide. Command attention with stunning visuals and intelligent structure.
        </p>

        {/* Input Field */}
        <div className="w-full max-w-2xl relative group">
          {/* Glowing background effect behind input */}
          <div className="absolute -inset-1 bg-gradient-to-r from-blue-600 to-cyan-600 rounded-xl opacity-40 blur-lg group-hover:opacity-60 transition duration-500"></div>

          <div className="relative flex items-center bg-[#0B1221] border border-blue-500/30 rounded-xl p-2 shadow-2xl">
            <div className="pl-4 pr-3 text-slate-400">
               <Sparkles className="w-5 h-5 text-blue-400" />
            </div>
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={handleKeyDown}
              disabled={isGenerating}
              placeholder="What do you want to create?"
              className="flex-1 bg-transparent text-white placeholder-slate-500 outline-none text-lg py-3 font-medium"
            />
            <button 
              onClick={handleGenerate}
              disabled={!query.trim() || isGenerating}
              className={`p-3 rounded-lg flex items-center justify-center transition-all duration-300 ${
                query.trim() && !isGenerating
                ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg shadow-blue-900/50' 
                : 'bg-slate-800 text-slate-500 cursor-not-allowed'
              }`}
            >
              {isGenerating ? (
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
              ) : (
                <ArrowRight className="w-5 h-5" />
              )}
            </button>
          </div>
        </div>

        {/* Suggestions / Footer Links */}
        <div className="mt-8 flex flex-wrap items-center justify-center gap-3 text-sm text-slate-400">
          <span className="flex items-center gap-2 opacity-70">
            <div className="border border-slate-600 rounded px-1.5 py-0.5 text-[10px]">Generate</div>
            Start from Scratch
          </span>
          <span className="mx-2 text-slate-700">•</span>
          <span className="opacity-70">Try:</span>
          {SUGGESTIONS.map((s, i) => (
            <button 
              key={i} 
              onClick={() => setQuery(s)}
              className="hover:text-blue-400 hover:underline transition-colors"
            >
              {s}
              {i < SUGGESTIONS.length - 1 && <span className="ml-3 no-underline text-slate-700 mx-1 inline-block decoration-transparent">•</span>}
            </button>
          ))}
        </div>

        {/* Error Message Toast */}
        {error && (
          <div className="mt-6 bg-red-500/10 border border-red-500/50 text-red-200 px-4 py-2 rounded-lg flex items-center gap-2 animate-pulse">
            <X size={16} /> {error}
          </div>
        )}
      </div>

      {/* Decorative large circles (faint background) - recreating the look from screenshot */}
      <div className="absolute top-1/2 left-[15%] w-[30vw] h-[30vw] border border-blue-500/10 rounded-full -translate-y-1/2 pointer-events-none"></div>
      <div className="absolute top-1/2 right-[15%] w-[30vw] h-[30vw] border border-blue-500/10 rounded-full -translate-y-1/2 pointer-events-none"></div>

    </div>
  );
}

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

