import React, { useState, useRef, useEffect } from 'react';
import { Send, Sparkles, X, Bot, Loader2 } from 'lucide-react';
import { SlideData } from '../types';
import { updatePresentation } from '../services/geminiService';

interface ChatAssistantProps {
  currentSlides: SlideData[];
  onUpdateSlides: (newSlides: SlideData[]) => void;
  onClose: () => void;
}

interface Message {
  role: 'user' | 'assistant';
  content: string;
}

const ChatAssistant: React.FC<ChatAssistantProps> = ({ currentSlides, onUpdateSlides, onClose }) => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { role: 'assistant', content: 'Hi! I can help you edit this presentation. What would you like to change?' }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setIsLoading(true);

    try {
      // Optimistic message
      // setMessages(prev => [...prev, { role: 'assistant', content: 'Working on that...' }]);

      const newSlides = await updatePresentation(currentSlides, userMsg);
      onUpdateSlides(newSlides);

      setMessages(prev => [...prev, { role: 'assistant', content: 'Done! I\'ve updated the presentation for you.' }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'assistant', content: 'Sorry, I encountered an error while updating the slides. Please try again.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="absolute top-20 right-6 w-96 h-[600px] glass-panel rounded-xl flex flex-col shadow-2xl z-50 animate-float border border-blue-500/20">
      {/* Header */}
      <div className="p-4 border-b border-white/10 flex items-center justify-between bg-gradient-to-r from-blue-900/40 to-indigo-900/40 rounded-t-xl">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center">
            <Bot size={18} className="text-white" />
          </div>
          <div>
            <h3 className="font-bold text-white text-sm">AI Editor</h3>
            <p className="text-[10px] text-blue-200">Powered by Gemini</p>
          </div>
        </div>
        <button onClick={onClose} className="text-white/50 hover:text-white transition-colors">
          <X size={18} />
        </button>
      </div>

      {/* Messages */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] px-4 py-3 rounded-2xl text-sm ${
              msg.role === 'user' 
              ? 'bg-blue-600 text-white rounded-br-none' 
              : 'bg-slate-700/80 text-slate-200 rounded-bl-none'
            }`}>
              {msg.content}
            </div>
          </div>
        ))}
        {isLoading && (
           <div className="flex justify-start">
             <div className="bg-slate-700/80 text-slate-200 px-4 py-3 rounded-2xl rounded-bl-none flex items-center gap-2">
               <Loader2 size={14} className="animate-spin text-blue-400" />
               <span className="text-xs">Thinking & Updating...</span>
             </div>
           </div>
        )}
      </div>

      {/* Input */}
      <div className="p-4 border-t border-white/10 bg-slate-900/40 rounded-b-xl">
        <div className="flex items-center gap-2 bg-slate-800/80 rounded-lg p-2 border border-slate-700 focus-within:border-blue-500 transition-colors">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Change slide 2 to..."
            className="flex-1 bg-transparent text-sm text-white placeholder-slate-400 outline-none"
            disabled={isLoading}
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className="p-1.5 bg-blue-600 hover:bg-blue-500 text-white rounded-md disabled:opacity-50 transition-colors"
          >
            <Send size={14} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatAssistant;

