import React from 'react';
import { SlideData, SlideLayout, Theme, TransitionType } from '../types';
import { Quote, List, Layout, Image as ImageIcon } from 'lucide-react';

interface SlideRendererProps {
  slide: SlideData;
  theme: Theme;
  transition: TransitionType;
}

const getAnimationClass = (type: TransitionType) => {
  switch (type) {
    case 'fade': return 'anim-fade-in';
    case 'slide-up': return 'anim-slide-up';
    case 'slide-down': return 'anim-slide-down';
    case 'slide-left': return 'anim-slide-left';
    case 'slide-right': return 'anim-slide-right';
    case 'zoom-in': return 'anim-zoom-in';
    case 'zoom-out': return 'anim-zoom-out';
    case 'flip-x': return 'anim-flip-in-x';
    case 'flip-y': return 'anim-flip-in-y';
    case 'rotate': return 'anim-rotate-in';
    case 'bounce': return 'anim-bounce-in';
    default: return '';
  }
};

const SlideRenderer: React.FC<SlideRendererProps> = ({ slide, theme, transition }) => {
  // Use custom image if available, otherwise fallback to keyword or abstract
  const imageUrl = slide.customImage 
    ? slide.customImage
    : slide.imageKeyword 
      ? `https://picsum.photos/seed/${encodeURIComponent(slide.imageKeyword)}/800/600` 
      : 'https://picsum.photos/seed/abstract/800/600';

  const animClass = getAnimationClass(transition);
  const bgStyle = { background: theme.bgGradient };
  const textPrimary = { color: theme.textPrimary };
  const textSecondary = { color: theme.textSecondary };
  const accentColor = { color: theme.accentColor };
  const borderStyle = { borderColor: `${theme.textSecondary}40` }; // 25% opacity

  const renderContent = () => {
    switch (slide.layout) {
      case SlideLayout.TITLE:
        return (
          <div className={`flex flex-col items-center justify-center h-full text-center px-12 ${animClass}`}>
            <h1 className="text-6xl font-bold mb-6 tracking-tight leading-tight" style={{ ...textPrimary, textShadow: '0 4px 20px rgba(0,0,0,0.3)' }}>
              {slide.title}
            </h1>
            {slide.subtitle && (
              <p className="text-2xl font-light max-w-2xl opacity-90" style={textSecondary}>{slide.subtitle}</p>
            )}
            <div className="mt-12 w-32 h-1 rounded-full" style={{ background: theme.accentColor }} />
          </div>
        );

      case SlideLayout.SECTION_HEADER:
        return (
          <div className={`flex flex-row items-center h-full ${animClass}`}>
            <div className="w-1/2 h-full flex items-center justify-center p-12 border-r" style={{ backgroundColor: 'rgba(0,0,0,0.1)', ...borderStyle }}>
               <h1 className="text-5xl font-bold leading-tight" style={textPrimary}>{slide.title}</h1>
            </div>
            <div className="w-1/2 h-full flex items-center justify-center p-12">
               <ul className="space-y-4">
                  {slide.content.map((point, i) => (
                    <li key={i} className="text-xl flex items-start" style={textSecondary}>
                      <span className="inline-block w-2 h-2 rounded-full mt-2.5 mr-4" style={{ backgroundColor: theme.accentColor }} />
                      {point}
                    </li>
                  ))}
               </ul>
            </div>
          </div>
        );

      case SlideLayout.QUOTE:
        return (
          <div className={`flex flex-col items-center justify-center h-full px-20 ${animClass}`}>
            <Quote className="w-16 h-16 opacity-50 mb-8" style={{ color: theme.accentColor }} />
            <blockquote className="text-4xl font-serif italic text-center leading-relaxed" style={textPrimary}>
              "{slide.content[0] || slide.subtitle}"
            </blockquote>
            <p className="mt-8 text-xl font-bold" style={{ color: theme.accentColor }}>— {slide.title}</p>
          </div>
        );

      case SlideLayout.TWO_COLUMN:
        return (
          <div className={`flex h-full ${animClass}`}>
            <div className="w-1/2 p-12 flex flex-col justify-center">
              <h2 className="text-4xl font-bold mb-8" style={textPrimary}>{slide.title}</h2>
              <div className="space-y-4">
                {slide.content.map((point, i) => (
                  <p key={i} className="text-lg leading-relaxed" style={textSecondary}>{point}</p>
                ))}
              </div>
            </div>
            <div className="w-1/2 p-6 flex items-center justify-center">
              <div className="w-full h-full max-h-[90%] rounded-xl overflow-hidden shadow-2xl bg-black/20 p-2 border" style={borderStyle}>
                <img 
                  src={imageUrl} 
                  alt="Slide visual" 
                  className="rounded-lg object-cover w-full h-full" 
                />
              </div>
            </div>
          </div>
        );

      case SlideLayout.BULLET_POINTS:
      default:
        return (
          <div className={`p-12 h-full flex flex-col ${animClass}`}>
            <div className="mb-8 border-b pb-4" style={borderStyle}>
               <h2 className="text-4xl font-bold" style={textPrimary}>{slide.title}</h2>
               {slide.subtitle && <p className="text-lg mt-2 font-medium" style={{ color: theme.accentColor }}>{slide.subtitle}</p>}
            </div>
            <div className="flex-1 flex flex-col justify-center">
              <ul className="space-y-5">
                {slide.content.map((point, i) => (
                  <li key={i} className="flex items-start p-4 rounded-lg transition-colors bg-white/5 border border-transparent hover:border-white/10">
                    <span className="flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold mr-4" style={{ backgroundColor: `${theme.accentColor}30`, color: theme.accentColor }}>
                      {i + 1}
                    </span>
                    <span className="text-xl" style={textSecondary}>{point}</span>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        );
    }
  };

  return (
    <div 
      className="w-full h-full rounded-xl overflow-hidden shadow-2xl relative transition-all duration-500"
      style={bgStyle}
    >
      {/* Subtle Texture/Pattern Overlay based on theme could go here */}
      <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')] pointer-events-none mix-blend-overlay"></div>

      {/* Decorative background blobs - dynamic opacity based on theme darkness */}
      <div className="absolute top-0 right-0 w-96 h-96 bg-white/5 rounded-full blur-3xl pointer-events-none transform translate-x-1/3 -translate-y-1/3 mix-blend-overlay" />
      <div className="absolute bottom-0 left-0 w-96 h-96 bg-black/10 rounded-full blur-3xl pointer-events-none transform -translate-x-1/3 translate-y-1/3 mix-blend-overlay" />

      {/* Content */}
      <div className="relative z-10 w-full h-full p-4">
        {renderContent()}
      </div>
    </div>
  );
};

export default SlideRenderer;

import React, { useState, useEffect } from 'react';
