const TRANSITIONS: { id: TransitionType; label: string }[] = [
  { id: 'none', label: 'None' },
  { id: 'fade', label: 'Fade' },
  { id: 'slide-up', label: 'Slide Up' },
  { id: 'slide-left', label: 'Slide Left' },
  { id: 'zoom-in', label: 'Zoom In' },
  { id: 'flip-x', label: 'Flip X' },
  { id: 'rotate', label: 'Rotate' },
  { id: 'bounce', label: 'Bounce' },
];

const SUGGESTIONS = [
  "Future of AI",
  "Cybersecurity",
  "Sustainable Energy",
  "Digital Marketing Strategy"
];

function App() {
  const [query, setQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedSlides, setGeneratedSlides] = useState<SlideData[] | null>(null);
  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);
  const [error, setError] = useState<string | null>(null);

  // Appearance State
  const [currentTheme, setCurrentTheme] = useState<Theme>(THEMES[0]);
  const [currentTransition, setCurrentTransition] = useState<TransitionType>('slide-up');

  // UI Toggles
  const [showChat, setShowChat] = useState(false);
  const [showMediaInput, setShowMediaInput] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [mediaUrl, setMediaUrl] = useState('');

  const handleGenerate = async () => {
    if (!query.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const slides = await generatePresentationContent(query);
      setGeneratedSlides(slides);
      setCurrentSlideIndex(0);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unexpected error occurred.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleGenerate();
  };

  const goHome = () => {
    setGeneratedSlides(null);
    setQuery('');
    setError(null);
    setShowChat(false);
  };

  const nextSlide = () => setCurrentSlideIndex(prev => Math.min(prev + 1, (generatedSlides?.length || 1) - 1));
  const prevSlide = () => setCurrentSlideIndex(prev => Math.max(prev - 1, 0));

  const updateSlides = (newSlides: SlideData[]) => {
    setGeneratedSlides(newSlides);
    if (currentSlideIndex >= newSlides.length) {
      setCurrentSlideIndex(Math.max(0, newSlides.length - 1));
    }
  };

  const updateCurrentNote = (note: string) => {
    if (!generatedSlides) return;
    const updated = [...generatedSlides];
    updated[currentSlideIndex] = { ...updated[currentSlideIndex], notes: note };
    setGeneratedSlides(updated);
  };

  const handleInsertMedia = () => {
    if (!generatedSlides || !mediaUrl) return;

    const updatedSlides = [...generatedSlides];
    updatedSlides[currentSlideIndex] = {
      ...updatedSlides[currentSlideIndex],
      customImage: mediaUrl
    };

    setGeneratedSlides(updatedSlides);
    setMediaUrl('');
    setShowMediaInput(false);
  };

  const addNewSlide = () => {
     if (!generatedSlides) return;
     const newSlide: SlideData = {
       title: "New Slide",
       content: ["Add your content here"],
       layout: "bullet_points" as any
     };
     const newSlides = [...generatedSlides];
     newSlides.splice(currentSlideIndex + 1, 0, newSlide);
     updateSlides(newSlides);
     setCurrentSlideIndex(currentSlideIndex + 1);
  };

  // --- EDITOR VIEW (3-Column Layout) ---
  if (generatedSlides) {
    return (
      <div className="h-screen w-full bg-[#0B0F17] flex flex-col text-white font-sans overflow-hidden">
        {/* Header matching screenshot */}
        <header className="h-14 border-b border-slate-800/60 bg-[#0B0F17] flex items-center justify-between px-4 shrink-0 z-30 relative">
            {/* Left: Back & Title */}
            <div className="flex items-center gap-4">
               <button onClick={goHome} className="flex items-center text-slate-400 hover:text-white transition-colors text-xs font-medium gap-1 uppercase tracking-wide">
                 <ArrowLeft size={14} /> Back
               </button>
               <div className="h-4 w-px bg-slate-800"></div>
               <h1 className="font-bold text-lg truncate max-w-[300px]">{query || "Untitled Presentation"}</h1>
            </div>

            {/* Right: Actions */}
            <div className="flex items-center gap-3">
               <button 
                 onClick={() => setShowChat(!showChat)}
                 className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs transition-all border ${showChat ? 'bg-blue-600/10 border-blue-500/50 text-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.2)]' : 'border-transparent text-slate-400 hover:text-white hover:bg-slate-800'}`}
               >
                 <Sparkles size={14} /> <span className="font-semibold">GeniusBot</span>
               </button>

               <div className="h-4 w-px bg-slate-800 mx-2"></div>

               <button className="text-slate-400 hover:text-white p-2 rounded-md hover:bg-slate-800" title="Export PDF">
                 <div className="flex items-center gap-1.5">
                   <Download size={16} /> 
                   <span className="text-xs font-medium hidden sm:inline">PDF</span>
                 </div>
               </button>

               <div className="relative">
                 <button 
                   onClick={() => setShowSettings(!showSettings)}
                   className={`p-2 rounded-md transition-colors ${showSettings ? 'text-blue-400 bg-slate-800' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
                 >
                    <Settings size={18} />
                 </button>

                 {/* Settings Popover */}
                 {showSettings && (
                   <div className="absolute top-full right-0 mt-2 w-64 glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in">
                      <div className="p-3 border-b border-white/10 text-xs font-bold text-slate-400 uppercase">Theme</div>
                      <div className="p-2 grid grid-cols-5 gap-1">
                        {THEMES.map(t => (
                          <button 
                            key={t.id}
                            onClick={() => setCurrentTheme(t)}
                            className={`w-8 h-8 rounded-full border-2 transition-transform hover:scale-110 ${currentTheme.id === t.id ? 'border-white scale-110' : 'border-transparent'}`}
                            style={{ background: t.accentColor }}
                            title={t.name}
                          />
                        ))}
                      </div>
                      <div className="p-3 border-b border-white/10 text-xs font-bold text-slate-400 uppercase mt-2">Transitions</div>
                      <div className="p-2 max-h-40 overflow-y-auto custom-scrollbar">
                        {TRANSITIONS.map(t => (
                          <button
                            key={t.id}
                            onClick={() => setCurrentTransition(t.id)}
                            className={`w-full text-left px-3 py-2 text-xs rounded-md transition-colors ${currentTransition === t.id ? 'bg-blue-600 text-white' : 'text-slate-300 hover:bg-slate-700'}`}
                          >
                            {t.label}
                          </button>
                        ))}
                      </div>
                   </div>
                 )}
               </div>

               <button className="text-slate-400 hover:text-white p-2 rounded-md hover:bg-slate-800">
                 <Grid size={18} />
               </button>

               <button className="ml-2 bg-blue-600 hover:bg-blue-500 text-white px-4 py-1.5 rounded-md text-sm font-semibold flex items-center gap-2 shadow-lg shadow-blue-900/30 transition-all hover:scale-105">
                 <Play size={14} fill="currentColor" /> Present
               </button>
            </div>
        </header>

        {/* Chat Assistant (Floating) */}
        {showChat && (
          <ChatAssistant 
            currentSlides={generatedSlides} 
            onUpdateSlides={updateSlides}
            onClose={() => setShowChat(false)}
          />
        )}

        {/* Insert Media Popover (Floating Centered) */}
        {showMediaInput && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
             <div className="glass-panel p-6 rounded-xl w-96 shadow-2xl animate-bounce-in border border-slate-700">
                <div className="flex justify-between items-center mb-4">
                   <h4 className="text-lg font-bold text-white">Insert Media</h4>
                   <button onClick={() => setShowMediaInput(false)} className="text-slate-400 hover:text-white"><X size={18}/></button>
                </div>
                <div className="space-y-4">
                  <div>
                    <label className="text-xs text-slate-400 mb-1 block">Image URL</label>
                    <input 
                      type="text" 
                      value={mediaUrl}
                      onChange={(e) => setMediaUrl(e.target.value)}
                      placeholder="https://source.unsplash.com/..."
                      className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-sm text-white outline-none focus:border-blue-500 transition-colors"
                    />
                  </div>
                  <button 
                    onClick={handleInsertMedia}
                    disabled={!mediaUrl}
                    className="w-full bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white py-2 rounded-lg font-medium transition-colors"
                  >
                    Add to Slide
                  </button>
                </div>
             </div>
          </div>
        )}

        {/* Body */}
        <div className="flex-1 flex overflow-hidden">
           {/* Left Sidebar: Slides */}
           <div className="w-64 flex flex-col border-r border-slate-800/60 bg-[#0F131C]">
              <div className="p-4 flex items-center justify-between border-b border-slate-800/40">
                 <span className="text-xs font-bold text-slate-500 tracking-wider">SLIDES</span>
                 <button onClick={addNewSlide} className="text-slate-400 hover:text-blue-400 transition-colors"><Plus size={18} /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
                 {generatedSlides.map((slide, idx) => (
                    <div 
                      key={idx}
                      onClick={() => setCurrentSlideIndex(idx)}
                      className={`group relative aspect-video rounded-lg border-2 cursor-pointer transition-all duration-200 ${
                        idx === currentSlideIndex 
                        ? 'border-blue-600 shadow-[0_0_0_2px_rgba(37,99,235,0.2)]' 
