                   <div className="absolute inset-0 bg-[#0B0F17]">
                     {/* Force re-render on transition/slide change */}
                     <div key={`${currentSlideIndex}-${currentTransition}`} className="w-full h-full">
                        <SlideRenderer 
                          slide={generatedSlides[currentSlideIndex]} 
                          theme={currentTheme} 
                          transition={currentTransition}
                        />
                     </div>
                   </div>
               </div>

               {/* Floating Controls (Bottom) */}
               <div className="mt-6 flex flex-col items-center gap-5 w-full max-w-2xl animate-slide-up">

                  {/* Action Bar */}
                  <div className="flex items-center gap-1 px-2 py-1.5 bg-slate-800/80 backdrop-blur-md rounded-full border border-slate-700/50 shadow-lg">
