                      <div className="w-px h-5 bg-slate-700 mx-1"></div>
                      <button onClick={() => setShowMediaInput(true)} className="text-xs font-medium text-slate-300 hover:text-white px-4 py-2 hover:bg-white/5 rounded-full transition-colors flex items-center gap-2 group">
