                       className="text-slate-400 hover:text-white disabled:opacity-30 transition-colors"
                     >
                       <ChevronLeft size={18} />
                     </button>
                     <span className="text-xs font-mono text-slate-400 font-medium tracking-wider">
                       {currentSlideIndex + 1} <span className="text-slate-600">/</span> {generatedSlides.length}
                     </span>
                     <button 
                       onClick={nextSlide}
                       disabled={currentSlideIndex === generatedSlides.length - 1}
                       className="text-slate-400 hover:text-white disabled:opacity-30 transition-colors"
                     >
                       <ChevronRight size={18} />
                     </button>
                  </div>
               </div>
           </div>

           {/* Right Sidebar: Speaker Notes */}
           <div className="w-80 border-l border-slate-800/60 bg-[#0F131C] flex flex-col z-20">
