          <Sparkles className="w-4 h-4 text-blue-400" />
          <span className="text-sm font-semibold text-blue-100">OrbitSlide AI 2.0</span>
        </div>

        {/* Hero Text */}
        <h1 className="text-6xl md:text-8xl font-black tracking-tight leading-[1.1] mb-2">
          Roar into
        </h1>
        <h1 className="text-6xl md:text-8xl font-black tracking-tight leading-[1.1] mb-8 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 via-cyan-400 to-blue-500 glow-text">
