export enum SlideLayout {
  TITLE = 'title',
  BULLET_POINTS = 'bullet_points',
  TWO_COLUMN = 'two_column',
  THREE_COLUMN = 'three_column', // New
  QUOTE = 'quote',
  SECTION_HEADER = 'section_header',
  BIG_NUMBER = 'big_number', // New
  GALLERY = 'gallery', // New
  COMPARISON = 'comparison', // New
  CODE_BLOCK = 'code_block' // New
}

export interface SlideData {
  title: string;
  subtitle?: string;
  content: string[];
  layout: SlideLayout;
  imageKeyword?: string; 
  customImage?: string; // URL for inserted media
  notes?: string;
}

export interface Presentation {
  topic: string;
  slides: SlideData[];
}

export type TransitionType = 
  | 'none'
  | 'fade'
  | 'slide-up'
  | 'slide-down'
  | 'slide-left'
  | 'slide-right'
  | 'zoom-in'
  | 'zoom-out'
  | 'flip-x'
  | 'flip-y'
  | 'rotate'
  | 'bounce'
  | 'elastic'
  | 'blur'
  | 'glitch';

export interface Theme {
  id: string;
  name: string;
  bgGradient: string;
  textPrimary: string;
  textSecondary: string;
  accentColor: string;
  fontFamily: string;
  cardBg: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { SlideData, SlideLayout } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY is not defined in the environment.");
  }
  return new GoogleGenAI({ apiKey });
};

const slideSchema = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING },
    subtitle: { type: Type.STRING },
    content: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING } 
    },
    layout: { 
      type: Type.STRING, 
      enum: [
        "title", 
        "bullet_points", 
        "two_column", 
        "three_column",
        "quote", 
        "section_header",
        "big_number",
        "gallery",
        "comparison",
        "code_block"
      ] 
    },
    imageKeyword: { type: Type.STRING },
    notes: { type: Type.STRING }
  },
  required: ["title", "content", "layout"]
};

export const generatePresentationContent = async (topic: string): Promise<SlideData[]> => {
  const ai = getClient();

  const prompt = `Create a professional presentation about: "${topic}". 
  Generate 6 to 8 slides. 
  Ensure variety in layouts (use comparison, big_number, or three_column where appropriate). 
  For 'imageKeyword', provide a short, descriptive search term for a stock photo.`;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash",
    contents: prompt,
    config: {
      systemInstruction: "You are a world-class presentation designer. You create engaging, structured slide decks with varied visual templates.",
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: slideSchema
      }
    }
  });

  if (response.text) {
    try {
      return JSON.parse(response.text) as SlideData[];
    } catch (e) {
      console.error("Failed to parse Gemini response", e);
      throw new Error("Failed to generate valid presentation data.");
    }
  }

  throw new Error("No content generated.");
};

export const updatePresentation = async (currentSlides: SlideData[], userInstruction: string): Promise<SlideData[]> => {
  const ai = getClient();

  const prompt = `
  Current Slides JSON: ${JSON.stringify(currentSlides)}

  User Instruction: "${userInstruction}"

  Task: Modify the slides based ONLY on the user instruction. Return the full updated array of slides.`;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash",
    contents: prompt,
    config: {
      systemInstruction: "You are an expert presentation editor.",
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: slideSchema
      }
    }
  });

  if (response.text) {
    try {
      return JSON.parse(response.text) as SlideData[];
    } catch (e) {
      console.error("Failed to parse Gemini update response", e);
      throw new Error("Failed to update presentation.");
    }
  }

  throw new Error("No update generated.");
};

import React from 'react';
import { SlideData, SlideLayout, Theme, TransitionType } from '../types';
import { Quote, Code, ArrowRightLeft } from 'lucide-react';

interface SlideRendererProps {
  slide: SlideData;
  theme: Theme;
  transition: TransitionType;
}

const getAnimationClass = (type: TransitionType) => {
  switch (type) {
    case 'fade': return 'anim-fade';
    case 'slide-up': return 'anim-slide-up';
    case 'slide-down': return 'anim-slide-down';
    case 'slide-left': return 'anim-slide-left';
    case 'slide-right': return 'anim-slide-right';
    case 'zoom-in': return 'anim-zoom-in';
    case 'zoom-out': return 'anim-zoom-out';
    case 'flip-x': return 'anim-flip-x';
    case 'flip-y': return 'anim-flip-y';
    case 'rotate': return 'anim-rotate';
    case 'bounce': return 'anim-bounce';
    case 'elastic': return 'anim-elastic';
    case 'blur': return 'anim-blur';
    case 'glitch': return 'anim-glitch';
    default: return '';
  }
};

const SlideRenderer: React.FC<SlideRendererProps> = ({ slide, theme, transition }) => {
  const imageUrl = slide.customImage 
    ? slide.customImage
    : slide.imageKeyword 
      ? `https://picsum.photos/seed/${encodeURIComponent(slide.imageKeyword)}/1200/800` 
      : 'https://picsum.photos/seed/abstract/1200/800';

  const animClass = getAnimationClass(transition);
  const containerStyle = { 
    background: theme.bgGradient,
    fontFamily: theme.fontFamily
  };
  const textPrimary = { color: theme.textPrimary };
  const textSecondary = { color: theme.textSecondary };
  const accentColor = { color: theme.accentColor };
  const cardStyle = { backgroundColor: theme.cardBg, borderColor: `${theme.textSecondary}20` };

  const renderContent = () => {
    switch (slide.layout) {
