            <h1 className="text-7xl font-bold mb-8 tracking-tight leading-tight drop-shadow-lg" style={textPrimary}>
              {slide.title}
            </h1>
            {slide.subtitle && (
              <p className="text-3xl font-light max-w-4xl opacity-90 leading-relaxed" style={textSecondary}>{slide.subtitle}</p>
