                      </div>
                  </div>
               </div>

               {/* Bottom Control Bar */}
               <div className="h-14 border-t border-slate-800/60 bg-[#0F131C] flex items-center justify-between px-6 shrink-0">
                  <div className="flex items-center gap-2">
                     <button className="text-xs font-medium text-slate-300 hover:text-white px-3 py-1.5 hover:bg-white/5 rounded transition-colors flex items-center gap-2">
