  { id: 'type-zoom-out', label: 'Zoom Out' },
  { id: 'type-flip-x', label: 'Flip X' },
  { id: 'type-flip-y', label: 'Flip Y' },
  { id: 'type-rotate-cw', label: 'Rotate CW' },
  { id: 'type-rotate-ccw', label: 'Rotate CCW' },
  { id: 'type-bounce', label: 'Bounce' },
  { id: 'type-elastic', label: 'Elastic' },
  { id: 'type-blur', label: 'Blur' },
  { id: 'type-glitch', label: 'Glitch' },
  { id: 'type-swing', label: 'Swing' },
  { id: 'type-wobble', label: 'Wobble' },
  { id: 'type-pulse', label: 'Pulse' },
  { id: 'type-heartbeat', label: 'Heartbeat' },
  { id: 'type-roll', label: 'Roll In' },
];

const ANIMATION_SPEEDS = [
  { id: 'speed-fast', label: 'Fast' },
  { id: 'speed-normal', label: 'Normal' },
  { id: 'speed-slow', label: 'Slow' },
  { id: 'speed-crawling', label: 'Cinematic' },
];

const ANIMATION_DELAYS = [
  { id: 'delay-none', label: 'No Delay' },
  { id: 'delay-short', label: 'Short Delay' },
  { id: 'delay-medium', label: 'Medium Delay' },
  { id: 'delay-long', label: 'Long Delay' },
];

const SUGGESTIONS = [
  "Future of AI",
  "Cybersecurity",
  "Sustainable Energy",
  "Digital Marketing Strategy"
];

function App() {
  const [query, setQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedSlides, setGeneratedSlides] = useState<SlideData[] | null>(null);
  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);
  const [error, setError] = useState<string | null>(null);

  // Appearance State
  const [currentTheme, setCurrentTheme] = useState<Theme>(THEMES[0]);

  // Animation State Configuration (Composite)
  const [animType, setAnimType] = useState('type-slide-up');
  const [animSpeed, setAnimSpeed] = useState('speed-normal');
  const [animDelay, setAnimDelay] = useState('delay-none');

  // Derived animation class string
  const currentAnimationClass = `anim-base ${animType} ${animSpeed} ${animDelay}`;

  // UI Toggles
  const [showChat, setShowChat] = useState(false);
  const [showMediaInput, setShowMediaInput] = useState(false);
  const [showThemes, setShowThemes] = useState(false);
  const [showAnimations, setShowAnimations] = useState(false);
  const [showTransitions, setShowTransitions] = useState(false); // Transition basically maps to same animation logic for now

  const [mediaUrl, setMediaUrl] = useState('');
  const [isPlaying, setIsPlaying] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const autoPlayRef = useRef<NodeJS.Timeout | null>(null);

  // Auto Play Logic
  useEffect(() => {
    if (isPlaying) {
      autoPlayRef.current = setInterval(() => {
        setCurrentSlideIndex(prev => {
           if (generatedSlides && prev < generatedSlides.length - 1) {
             return prev + 1;
           } else {
             setIsPlaying(false);
             return prev;
           }
        });
      }, 3000); // 3 seconds per slide
    } else {
      if (autoPlayRef.current) clearInterval(autoPlayRef.current);
    }
    return () => {
      if (autoPlayRef.current) clearInterval(autoPlayRef.current);
    };
  }, [isPlaying, generatedSlides]);

  const handleGenerate = async () => {
    if (!query.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const slides = await generatePresentationContent(query);
      setGeneratedSlides(slides);
      setCurrentSlideIndex(0);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unexpected error occurred.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleGenerate();
  };

  const goHome = () => {
    setGeneratedSlides(null);
    setQuery('');
    setError(null);
    setShowChat(false);
    setIsPlaying(false);
  };

  const nextSlide = () => setCurrentSlideIndex(prev => Math.min(prev + 1, (generatedSlides?.length || 1) - 1));
  const prevSlide = () => setCurrentSlideIndex(prev => Math.max(prev - 1, 0));

  const updateSlides = (newSlides: SlideData[]) => {
    setGeneratedSlides(newSlides);
    if (currentSlideIndex >= newSlides.length) {
      setCurrentSlideIndex(Math.max(0, newSlides.length - 1));
    }
  };

  const updateCurrentSlide = (updatedSlide: SlideData) => {
    if (!generatedSlides) return;
    const newSlides = [...generatedSlides];
    newSlides[currentSlideIndex] = updatedSlide;
    setGeneratedSlides(newSlides);
  };

  const updateCurrentNote = (note: string) => {
    if (!generatedSlides) return;
    updateCurrentSlide({ ...generatedSlides[currentSlideIndex], notes: note });
  };

  const handleInsertMediaUrl = () => {
    if (!generatedSlides || !mediaUrl) return;
    updateCurrentSlide({
      ...generatedSlides[currentSlideIndex],
      customImage: mediaUrl
    });
    setMediaUrl('');
    setShowMediaInput(false);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file && generatedSlides) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        updateCurrentSlide({
           ...generatedSlides[currentSlideIndex],
           customImage: result
        });
        setShowMediaInput(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const addNewSlide = () => {
     if (!generatedSlides) return;
     const newSlide: SlideData = {
       title: "New Slide",
       content: ["Add your content here"],
       layout: "bullet_points" as any
     };
     const newSlides = [...generatedSlides];
     newSlides.splice(currentSlideIndex + 1, 0, newSlide);
     updateSlides(newSlides);
     setCurrentSlideIndex(currentSlideIndex + 1);
  };

  const addTextToSlide = () => {
    if (!generatedSlides) return;
    const current = generatedSlides[currentSlideIndex];
    const newContent = [...current.content, "New Text Block"];
    updateCurrentSlide({ ...current, content: newContent });
  };

  // --- EDITOR VIEW ---
  if (generatedSlides) {
    return (
      <div className="h-screen w-full bg-[#0B0F17] flex flex-col text-white font-sans overflow-hidden">
        {/* Header */}
        <header className="h-14 border-b border-slate-800/60 bg-[#0B0F17] flex items-center justify-between px-4 shrink-0 z-30 relative shadow-md">
            <div className="flex items-center gap-4">
               <button onClick={goHome} className="flex items-center text-slate-400 hover:text-white transition-colors text-xs font-medium gap-1 uppercase tracking-wide">
                 <ArrowLeft size={14} /> Back
               </button>
               <div className="h-4 w-px bg-slate-800"></div>
               <h1 className="font-bold text-lg truncate max-w-[200px] text-slate-200">{query || "Untitled Presentation"}</h1>
            </div>

            {/* Top Right Controls - SEPARATED */}
            <div className="flex items-center gap-2">

               {/* THEMES DROPDOWN */}
               <div className="relative">
                 <button 
                   onClick={() => { setShowThemes(!showThemes); setShowAnimations(false); setShowTransitions(false); }}
                   className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${showThemes ? 'bg-blue-600 text-white' : 'text-slate-300 hover:bg-slate-800'}`}
                 >
                   <Palette size={14} /> Themes
                 </button>
                 {showThemes && (
                    <div className="absolute top-full right-0 mt-2 w-72 glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in border border-slate-700">
                      <div className="p-3 border-b border-white/10 flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-400 uppercase">Select Theme</span>
                        <X size={14} className="cursor-pointer text-slate-500 hover:text-white" onClick={() => setShowThemes(false)} />
                      </div>
                      <div className="p-3 grid grid-cols-4 gap-2 max-h-64 overflow-y-auto custom-scrollbar">
                        {THEMES.map(t => (
                          <button 
                            key={t.id}
                            onClick={() => setCurrentTheme(t)}
                            className={`w-full aspect-square rounded-full border-2 transition-all hover:scale-110 ${currentTheme.id === t.id ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-80 hover:opacity-100'}`}
                            style={{ background: t.accentColor }}
                            title={t.name}
                          />
                        ))}
                      </div>
                    </div>
                 )}
               </div>

               {/* ANIMATIONS DROPDOWN */}
               <div className="relative">
                 <button 
                   onClick={() => { setShowAnimations(!showAnimations); setShowThemes(false); setShowTransitions(false); }}
                   className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${showAnimations ? 'bg-blue-600 text-white' : 'text-slate-300 hover:bg-slate-800'}`}
                 >
                   <Move size={14} /> Animations
                 </button>
                 {showAnimations && (
                    <div className="absolute top-full right-0 mt-2 w-64 glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in border border-slate-700">
                      <div className="p-3 border-b border-white/10 flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-400 uppercase">Entry Animation</span>
                        <X size={14} className="cursor-pointer text-slate-500 hover:text-white" onClick={() => setShowAnimations(false)} />
                      </div>
                      <div className="p-2 max-h-64 overflow-y-auto custom-scrollbar space-y-1">
                        {ANIMATION_TYPES.map(t => (
                          <button
                            key={t.id}
                            onClick={() => setAnimType(t.id)}
                            className={`w-full text-left px-3 py-2 text-xs rounded-md transition-colors flex justify-between ${animType === t.id ? 'bg-blue-600 text-white' : 'text-slate-300 hover:bg-slate-700'}`}
                          >
                            {t.label}
                            {animType === t.id && <Zap size={12} />}
                          </button>
                        ))}
                      </div>
                      <div className="p-2 border-t border-white/10 bg-slate-900/50">
                         <div className="text-[10px] text-slate-500 mb-1 uppercase font-bold">Speed</div>
                         <div className="flex gap-1 mb-2">
                            {ANIMATION_SPEEDS.map(s => (
                              <button key={s.id} onClick={() => setAnimSpeed(s.id)} className={`flex-1 py-1 rounded text-[10px] ${animSpeed === s.id ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400'}`}>{s.label}</button>
                            ))}
                         </div>
                         <div className="text-[10px] text-slate-500 mb-1 uppercase font-bold">Delay</div>
                         <div className="flex gap-1">
                            {ANIMATION_DELAYS.map(d => (
                              <button key={d.id} onClick={() => setAnimDelay(d.id)} className={`flex-1 py-1 rounded text-[10px] ${animDelay === d.id ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400'}`}>{d.label}</button>
                            ))}
                         </div>
                      </div>
                    </div>
                 )}
               </div>

               <div className="h-4 w-px bg-slate-800 mx-1"></div>

               <button 
                 onClick={() => setShowChat(!showChat)}
                 className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs transition-all border ${showChat ? 'bg-blue-600/10 border-blue-500/50 text-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.2)]' : 'border-transparent text-slate-400 hover:text-white hover:bg-slate-800'}`}
               >
                 <Sparkles size={14} /> <span className="font-semibold">GeniusBot</span>
               </button>

               <div className="h-4 w-px bg-slate-800 mx-1"></div>

               <button className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-1.5 rounded-md text-sm font-semibold flex items-center gap-2 shadow-lg shadow-blue-900/30 transition-all hover:scale-105">
                 <Play size={14} fill="currentColor" /> Present
               </button>
            </div>
        </header>

        {showChat && (
          <ChatAssistant 
            currentSlides={generatedSlides} 
            onUpdateSlides={updateSlides}
            onClose={() => setShowChat(false)}
          />
        )}

        {/* Insert Media Popover */}
        {showMediaInput && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
             <div className="glass-panel p-6 rounded-xl w-[400px] shadow-2xl animate-bounce-in border border-slate-700 relative">
                <button onClick={() => setShowMediaInput(false)} className="absolute top-4 right-4 text-slate-400 hover:text-white"><X size={18}/></button>
                <h4 className="text-xl font-bold text-white mb-6">Insert Media</h4>

                <div className="space-y-6">
                  {/* Upload from Device */}
                  <div className="border-2 border-dashed border-slate-700 rounded-lg p-6 flex flex-col items-center justify-center hover:border-blue-500 hover:bg-slate-800/30 transition-all cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
                     <Upload size={32} className="text-slate-500 group-hover:text-blue-400 mb-2" />
                     <span className="text-sm text-slate-300 font-medium">Upload from Device</span>
                     <span className="text-xs text-slate-500 mt-1">JPG, PNG, GIF up to 5MB</span>
                     <input 
                       type="file" 
                       ref={fileInputRef} 
                       className="hidden" 
                       accept="image/*"
                       onChange={handleFileUpload}
                     />
                  </div>

                  <div className="relative flex py-2 items-center">
                    <div className="flex-grow border-t border-slate-700"></div>
                    <span className="flex-shrink-0 mx-4 text-slate-500 text-xs uppercase">Or via URL</span>
                    <div className="flex-grow border-t border-slate-700"></div>
                  </div>

                  {/* URL Input */}
                  <div>
                    <div className="flex items-center gap-2 bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 focus-within:border-blue-500 transition-colors">
                      <Globe size={16} className="text-slate-500" />
                      <input 
                        type="text" 
                        value={mediaUrl}
                        onChange={(e) => setMediaUrl(e.target.value)}
                        placeholder="https://example.com/image.jpg"
                        className="flex-1 bg-transparent text-sm text-white outline-none"
                      />
                    </div>
                    <button 
                      onClick={handleInsertMediaUrl}
                      disabled={!mediaUrl}
                      className="w-full mt-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white py-2 rounded-lg font-medium transition-colors"
                    >
                      Insert from URL
                    </button>
                  </div>
                </div>
             </div>
          </div>
        )}

        {/* Body */}
        <div className="flex-1 flex overflow-hidden">
           {/* Left Sidebar */}
           <div className="w-56 flex flex-col border-r border-slate-800/60 bg-[#0F131C] shrink-0">
              <div className="p-4 flex items-center justify-between border-b border-slate-800/40">
                 <span className="text-xs font-bold text-slate-500 tracking-wider">SLIDES</span>
                 <button onClick={addNewSlide} className="text-slate-400 hover:text-blue-400 transition-colors" title="Add New Slide"><Plus size={18} /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-3 space-y-3 custom-scrollbar">
                 {generatedSlides.map((slide, idx) => (
                    <div 
                      key={idx}
                      onClick={() => setCurrentSlideIndex(idx)}
                      className={`group relative aspect-video rounded-lg border-2 cursor-pointer transition-all duration-200 ${
                        idx === currentSlideIndex 
                        ? 'border-blue-600 shadow-[0_0_0_2px_rgba(37,99,235,0.2)]' 
                        : 'border-slate-800 hover:border-slate-600 opacity-60 hover:opacity-100'
                      }`}
                    >
                       <div className="absolute inset-0 bg-slate-900 rounded-md overflow-hidden">
                          {/* Thumbnails approximated */}
                          <div className="w-full h-full p-2 flex flex-col items-center justify-center scale-50 origin-center select-none opacity-50">
                             <div className="w-full h-1 bg-slate-600 rounded mb-1"></div>
                             <div className="w-2/3 h-1 bg-slate-700 rounded"></div>
                          </div>
                       </div>
                       <div className={`absolute top-1 left-1 w-4 h-4 rounded flex items-center justify-center text-[9px] font-bold shadow-sm ${
                         idx === currentSlideIndex ? 'bg-blue-600 text-white' : 'bg-black/60 text-slate-400'
                       }`}>
                         {idx + 1}
                       </div>
                    </div>
                 ))}
              </div>
           </div>

           {/* Center Canvas */}
           <div className="flex-1 bg-[#05080f] relative flex flex-col">
               <div className="flex-1 flex items-center justify-center p-4 lg:p-8 overflow-hidden">
                  <div className="relative w-full h-full flex items-center justify-center">
                      {/* Scale container to fit but keep aspect ratio */}
                      <div className="aspect-video w-full max-h-full shadow-2xl rounded-lg overflow-hidden ring-1 ring-slate-800/50 relative bg-black">
                         {/* Force re-render on animation change */}
                         <div key={`${currentSlideIndex}-${currentAnimationClass}`} className="w-full h-full">
                            <SlideRenderer 
                              slide={generatedSlides[currentSlideIndex]} 
                              theme={currentTheme} 
                              animationClass={currentAnimationClass}
                              onUpdate={updateCurrentSlide}
                            />
                         </div>
                      </div>
                  </div>
               </div>

               {/* Bottom Control Bar */}
               <div className="h-14 border-t border-slate-800/60 bg-[#0F131C] flex items-center justify-between px-6 shrink-0">
                  <div className="flex items-center gap-2">
                     <button onClick={addTextToSlide} className="text-xs font-medium text-slate-300 hover:text-white px-3 py-1.5 hover:bg-white/5 rounded transition-colors flex items-center gap-2 group">
                        <Type size={14} className="text-blue-400" /> Add Text
                     </button>
                     <div className="w-px h-4 bg-slate-800 mx-1"></div>
                     <button onClick={() => setShowMediaInput(true)} className="text-xs font-medium text-slate-300 hover:text-white px-3 py-1.5 hover:bg-white/5 rounded transition-colors flex items-center gap-2 group">
                        <ImageIcon size={14} className="group-hover:text-blue-400 transition-colors" /> Media
                     </button>
                  </div>

                  <div className="flex items-center gap-4">
                     <button 
                       onClick={prevSlide}
                       disabled={currentSlideIndex === 0}
                       className="p-1.5 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white disabled:opacity-30 transition-colors"
                     >
                       <ChevronLeft size={20} />
                     </button>
                     <span className="text-xs font-mono text-slate-400 font-medium">
                       {currentSlideIndex + 1} / {generatedSlides.length}
                     </span>
                     <button 
                       onClick={nextSlide}
                       disabled={currentSlideIndex === generatedSlides.length - 1}
                       className="p-1.5 rounded-full hover:bg-slate-800 text-slate-400 hover:text-white disabled:opacity-30 transition-colors"
                     >
                       <ChevronRight size={20} />
                     </button>
                  </div>

                  <div className="w-32 flex justify-end">
                     {/* Auto Play Toggle */}
                     <button 
                       onClick={() => setIsPlaying(!isPlaying)}
                       className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-semibold transition-all ${isPlaying ? 'bg-green-500/20 text-green-400 border border-green-500/50' : 'text-slate-400 hover:text-white hover:bg-slate-800 border border-transparent'}`}
                     >
                       {isPlaying ? <Pause size={12} fill="currentColor" /> : <MonitorPlay size={12} />}
                       {isPlaying ? 'Auto' : 'Auto'}
                     </button>
                  </div>
               </div>
           </div>

           {/* Right Sidebar: Speaker Notes */}
           <div className="w-72 border-l border-slate-800/60 bg-[#0F131C] flex flex-col shrink-0">
              <div className="p-3 border-b border-slate-800/40 bg-[#0F131C]">
                 <span className="text-[10px] font-bold text-slate-500 tracking-wider">NOTES</span>
              </div>
              <div className="flex-1 relative">
                <textarea 
                   className="w-full h-full bg-transparent p-4 text-xs text-slate-300 resize-none outline-none leading-relaxed font-normal placeholder-slate-700 custom-scrollbar"
                   value={generatedSlides[currentSlideIndex].notes || ''}
                   onChange={(e) => updateCurrentNote(e.target.value)}
                   placeholder="Add speaker notes..."
                   spellCheck={false}
                />
              </div>
           </div>
        </div>
      </div>
    );
  }

  // --- VIEW: HOME ---
  return (
    <div className="relative min-h-screen w-full overflow-hidden flex flex-col items-center justify-center">
      <StarBackground />
      {/* (Home Screen Content) */}
      <div className="absolute top-8 left-8 z-10 flex flex-col">
        <span className="text-[10px] uppercase tracking-[0.2em] text-slate-400 font-bold mb-1">Presented by</span>
        <div className="flex items-center gap-2">
            <div className="h-6 w-1 bg-blue-500 rounded-full"></div>
            <span className="text-2xl font-black tracking-widest text-white">NEXZI</span>
        </div>
      </div>

      <div className="relative z-10 flex flex-col items-center max-w-4xl w-full px-4 text-center">
        <div className="mb-8 inline-flex items-center gap-2 px-4 py-1.5 rounded-full border border-blue-500/30 bg-blue-950/30 backdrop-blur-md shadow-[0_0_20px_rgba(59,130,246,0.3)] animate-float">
          <Sparkles className="w-4 h-4 text-blue-400" />
          <span className="text-sm font-semibold text-blue-100">OrbitSlide AI 3.0</span>
        </div>
        <h1 className="text-6xl md:text-8xl font-black tracking-tight leading-[1.1] mb-2">Roar into</h1>
        <h1 className="text-6xl md:text-8xl font-black tracking-tight leading-[1.1] mb-8 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 via-cyan-400 to-blue-500 glow-text">Greatness.</h1>
        <p className="max-w-2xl text-lg md:text-xl text-slate-300 font-light leading-relaxed mb-12 opacity-90">Unleash the power of AI to create professional slide decks instantly.</p>

        <div className="w-full max-w-2xl relative group">
          <div className="absolute -inset-1 bg-gradient-to-r from-blue-600 to-cyan-600 rounded-xl opacity-40 blur-lg group-hover:opacity-60 transition duration-500"></div>
          <div className="relative flex items-center bg-[#0B1221] border border-blue-500/30 rounded-xl p-2 shadow-2xl">
            <div className="pl-4 pr-3 text-slate-400"><Sparkles className="w-5 h-5 text-blue-400" /></div>
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={handleKeyDown}
              disabled={isGenerating}
              placeholder="What do you want to create?"
              className="flex-1 bg-transparent text-white placeholder-slate-500 outline-none text-lg py-3 font-medium"
            />
            <button 
              onClick={handleGenerate}
              disabled={!query.trim() || isGenerating}
              className={`p-3 rounded-lg flex items-center justify-center transition-all duration-300 ${query.trim() && !isGenerating ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg shadow-blue-900/50' : 'bg-slate-800 text-slate-500 cursor-not-allowed'}`}
            >
              {isGenerating ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : <ArrowRight className="w-5 h-5" />}
            </button>
          </div>
        </div>

        <div className="mt-8 flex flex-wrap items-center justify-center gap-3 text-sm text-slate-400">
          <span className="flex items-center gap-2 opacity-70">
            <div className="border border-slate-600 rounded px-1.5 py-0.5 text-[10px]">Generate</div>
            Start from Scratch
          </span>
          <span className="mx-2 text-slate-700">•</span>
          <span className="opacity-70">Try:</span>
          {SUGGESTIONS.map((s, i) => (
            <button key={i} onClick={() => setQuery(s)} className="hover:text-blue-400 hover:underline transition-colors">{s}</button>
          ))}
        </div>
        {error && <div className="mt-6 bg-red-500/10 border border-red-500/50 text-red-200 px-4 py-2 rounded-lg flex items-center gap-2 animate-pulse"><X size={16} /> {error}</div>}
      </div>
      <div className="absolute top-1/2 left-[15%] w-[30vw] h-[30vw] border border-blue-500/10 rounded-full -translate-y-1/2 pointer-events-none"></div>
      <div className="absolute top-1/2 right-[15%] w-[30vw] h-[30vw] border border-blue-500/10 rounded-full -translate-y-1/2 pointer-events-none"></div>
    </div>
  );
}

export default App;

