            <div className="flex items-center gap-4">
               <button onClick={goHome} className="flex items-center text-slate-400 hover:text-white transition-colors text-xs font-medium gap-1 uppercase tracking-wide">
                 <ArrowLeft size={14} /> Back
               </button>
               <div className="h-4 w-px bg-slate-800"></div>
               <h1 className="font-bold text-lg truncate max-w-[200px] text-slate-200">{query || "Untitled Presentation"}</h1>
            </div>

            {/* Top Right Controls - SEPARATED */}
            <div className="flex items-center gap-2">

               {/* THEMES DROPDOWN */}
               <div className="relative">
                 <button 
                   onClick={() => { setShowThemes(!showThemes); setShowAnimations(false); setShowTransitions(false); }}
                   className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${showThemes ? 'bg-blue-600 text-white' : 'text-slate-300 hover:bg-slate-800'}`}
                 >
                   <Palette size={14} /> Themes
                 </button>
                 {showThemes && (
                    <div className="absolute top-full right-0 mt-2 w-72 glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in border border-slate-700">
                      <div className="p-3 border-b border-white/10 flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-400 uppercase">Select Theme</span>
                        <X size={14} className="cursor-pointer text-slate-500 hover:text-white" onClick={() => setShowThemes(false)} />
                      </div>
                      <div className="p-3 grid grid-cols-4 gap-2 max-h-64 overflow-y-auto custom-scrollbar">
                        {THEMES.map(t => (
                          <button 
                            key={t.id}
                            onClick={() => setCurrentTheme(t)}
                            className={`w-full aspect-square rounded-full border-2 transition-all hover:scale-110 ${currentTheme.id === t.id ? 'border-white scale-110 shadow-lg' : 'border-transparent opacity-80 hover:opacity-100'}`}
                            style={{ background: t.accentColor }}
                            title={t.name}
                          />
                        ))}
                      </div>
                    </div>
                 )}
               </div>

               {/* ANIMATIONS DROPDOWN */}
               <div className="relative">
                 <button 
                   onClick={() => { setShowAnimations(!showAnimations); setShowThemes(false); setShowTransitions(false); }}
                   className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${showAnimations ? 'bg-blue-600 text-white' : 'text-slate-300 hover:bg-slate-800'}`}
                 >
                   <Move size={14} /> Animations
                 </button>
                 {showAnimations && (
                    <div className="absolute top-full right-0 mt-2 w-64 glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in border border-slate-700">
                      <div className="p-3 border-b border-white/10 flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-400 uppercase">Entry Animation</span>
                        <X size={14} className="cursor-pointer text-slate-500 hover:text-white" onClick={() => setShowAnimations(false)} />
                      </div>
                      <div className="p-2 max-h-64 overflow-y-auto custom-scrollbar space-y-1">
                        {ANIMATION_TYPES.map(t => (
                          <button
                            key={t.id}
                            onClick={() => setAnimType(t.id)}
                            className={`w-full text-left px-3 py-2 text-xs rounded-md transition-colors flex justify-between ${animType === t.id ? 'bg-blue-600 text-white' : 'text-slate-300 hover:bg-slate-700'}`}
                          >
                            {t.label}
                            {animType === t.id && <Zap size={12} />}
                          </button>
                        ))}
                      </div>
                      <div className="p-2 border-t border-white/10 bg-slate-900/50">
                         <div className="text-[10px] text-slate-500 mb-1 uppercase font-bold">Speed</div>
                         <div className="flex gap-1 mb-2">
                            {ANIMATION_SPEEDS.map(s => (
                              <button key={s.id} onClick={() => setAnimSpeed(s.id)} className={`flex-1 py-1 rounded text-[10px] ${animSpeed === s.id ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400'}`}>{s.label}</button>
                            ))}
                         </div>
                         <div className="text-[10px] text-slate-500 mb-1 uppercase font-bold">Delay</div>
                         <div className="flex gap-1">
                            {ANIMATION_DELAYS.map(d => (
                              <button key={d.id} onClick={() => setAnimDelay(d.id)} className={`flex-1 py-1 rounded text-[10px] ${animDelay === d.id ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400'}`}>{d.label}</button>
                            ))}
                         </div>
                      </div>
                    </div>
                 )}
               </div>

               <div className="h-4 w-px bg-slate-800 mx-1"></div>

               <button 
                 onClick={() => setShowChat(!showChat)}
                 className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs transition-all border ${showChat ? 'bg-blue-600/10 border-blue-500/50 text-blue-400 shadow-[0_0_15px_rgba(59,130,246,0.2)]' : 'border-transparent text-slate-400 hover:text-white hover:bg-slate-800'}`}
               >
                 <Sparkles size={14} /> <span className="font-semibold">GeniusBot</span>
               </button>

               <div className="h-4 w-px bg-slate-800 mx-1"></div>

               <button className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-1.5 rounded-md text-sm font-semibold flex items-center gap-2 shadow-lg shadow-blue-900/30 transition-all hover:scale-105">
                 <Play size={14} fill="currentColor" /> Present
               </button>
            </div>
        </header>

        {showChat && (
          <ChatAssistant 
            currentSlides={generatedSlides} 
            onUpdateSlides={updateSlides}
            onClose={() => setShowChat(false)}
          />
        )}

        {/* Insert Media Popover */}
        {showMediaInput && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
             <div className="glass-panel p-6 rounded-xl w-[400px] shadow-2xl animate-bounce-in border border-slate-700 relative">
                <button onClick={() => setShowMediaInput(false)} className="absolute top-4 right-4 text-slate-400 hover:text-white"><X size={18}/></button>
                <h4 className="text-xl font-bold text-white mb-6">Insert Media</h4>

                <div className="space-y-6">
                  {/* Upload from Device */}
                  <div className="border-2 border-dashed border-slate-700 rounded-lg p-6 flex flex-col items-center justify-center hover:border-blue-500 hover:bg-slate-800/30 transition-all cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
                     <Upload size={32} className="text-slate-500 group-hover:text-blue-400 mb-2" />
                     <span className="text-sm text-slate-300 font-medium">Upload from Device</span>
                     <span className="text-xs text-slate-500 mt-1">JPG, PNG, GIF up to 5MB</span>
                     <input 
                       type="file" 
                       ref={fileInputRef} 
                       className="hidden" 
                       accept="image/*"
                       onChange={handleFileUpload}
                     />
                  </div>

                  <div className="relative flex py-2 items-center">
                    <div className="flex-grow border-t border-slate-700"></div>
                    <span className="flex-shrink-0 mx-4 text-slate-500 text-xs uppercase">Or via URL</span>
                    <div className="flex-grow border-t border-slate-700"></div>
                  </div>

                  {/* URL Input */}
                  <div>
                    <div className="flex items-center gap-2 bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 focus-within:border-blue-500 transition-colors">
                      <Globe size={16} className="text-slate-500" />
                      <input 
                        type="text" 
                        value={mediaUrl}
                        onChange={(e) => setMediaUrl(e.target.value)}
                        placeholder="https://example.com/image.jpg"
                        className="flex-1 bg-transparent text-sm text-white outline-none"
                      />
                    </div>
                    <button 
                      onClick={handleInsertMediaUrl}
                      disabled={!mediaUrl}
                      className="w-full mt-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white py-2 rounded-lg font-medium transition-colors"
                    >
                      Insert from URL
                    </button>
                  </div>
                </div>
             </div>
          </div>
