function App() {
  const [query, setQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedSlides, setGeneratedSlides] = useState<SlideData[] | null>(null);
  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);
  const [error, setError] = useState<string | null>(null);

  // Appearance State
  const [currentTheme, setCurrentTheme] = useState<Theme>(THEME_CATEGORIES[0].items[0]);

  // Animation State
  const [animType, setAnimType] = useState('type-slide-up');
  const [animSpeed, setAnimSpeed] = useState('speed-normal');
  const [animDelay, setAnimDelay] = useState('delay-none');

  // Settings
  const [autoAdvance, setAutoAdvance] = useState(false);

  // Derived animation class
  const currentAnimationClass = `anim-base ${animType} ${animSpeed} ${animDelay}`;

  // UI Toggles
  const [activeMenu, setActiveMenu] = useState<'none' | 'themes' | 'animations' | 'transitions' | 'settings'>('none');
  const [showChat, setShowChat] = useState(false);
  const [showMediaInput, setShowMediaInput] = useState(false);

  // Responsive UI States
  const [showLeftSidebar, setShowLeftSidebar] = useState(true);
  const [showRightSidebar, setShowRightSidebar] = useState(true);

  // Scaling State
  const canvasRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(1);

  const [mediaUrl, setMediaUrl] = useState('');
  const [isPlaying, setIsPlaying] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const autoPlayRef = useRef<number | null>(null);

  // Handle Resize for Scaling
  useEffect(() => {
    const handleResize = () => {
      if (!canvasRef.current) return;
      const { width, height } = canvasRef.current.getBoundingClientRect();
      const targetWidth = 1280;
      const targetHeight = 720;

      const widthRatio = (width - 40) / targetWidth; // 40px padding buffer
      const heightRatio = (height - 40) / targetHeight;

      // Use the smaller ratio to ensure it fits entirely
      const newScale = Math.min(widthRatio, heightRatio);
      setScale(Math.max(0.1, newScale)); // Prevent scale 0
    };

    // Initial calc
    handleResize();

    // Resize listener
    window.addEventListener('resize', handleResize);

    // Adjust sidebars on mobile
    if (window.innerWidth < 1024) {
      setShowLeftSidebar(false);
      setShowRightSidebar(false);
    }

    return () => window.removeEventListener('resize', handleResize);
  }, [generatedSlides, showLeftSidebar, showRightSidebar]);

  // Auto Play Logic
  useEffect(() => {
    const shouldPlay = isPlaying || autoAdvance;

    if (shouldPlay && generatedSlides) {
      autoPlayRef.current = window.setInterval(() => {
        setCurrentSlideIndex(prev => {
           if (prev < generatedSlides.length - 1) {
             return prev + 1;
           } else {
             if (isPlaying) setIsPlaying(false);
             return prev; 
           }
        });
      }, 3000); 
    } else {
      if (autoPlayRef.current) window.clearInterval(autoPlayRef.current);
    }
    return () => {
      if (autoPlayRef.current) window.clearInterval(autoPlayRef.current);
    };
  }, [isPlaying, autoAdvance, generatedSlides]);

  const handleGenerate = async () => {
    if (!query.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const slides = await generatePresentationContent(query);
      setGeneratedSlides(slides);
      setCurrentSlideIndex(0);
      // Auto-hide sidebars on mobile after generation to focus on content
      if (window.innerWidth < 1024) {
        setShowLeftSidebar(false);
        setShowRightSidebar(false);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unexpected error occurred.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleGenerate();
  };

  const goHome = () => {
    setGeneratedSlides(null);
    setQuery('');
    setError(null);
    setShowChat(false);
    setIsPlaying(false);
    setActiveMenu('none');
  };

  const nextSlide = () => setCurrentSlideIndex(prev => Math.min(prev + 1, (generatedSlides?.length || 1) - 1));
  const prevSlide = () => setCurrentSlideIndex(prev => Math.max(prev - 1, 0));

  const updateSlides = (newSlides: SlideData[]) => {
    setGeneratedSlides(newSlides);
    if (currentSlideIndex >= newSlides.length) {
      setCurrentSlideIndex(Math.max(0, newSlides.length - 1));
    }
  };

  const updateCurrentSlide = (updatedSlide: SlideData) => {
    if (!generatedSlides) return;
    const newSlides = [...generatedSlides];
    newSlides[currentSlideIndex] = updatedSlide;
    setGeneratedSlides(newSlides);
  };

  const updateCurrentNote = (note: string) => {
    if (!generatedSlides) return;
    updateCurrentSlide({ ...generatedSlides[currentSlideIndex], notes: note });
  };

  const handleInsertMediaUrl = () => {
    if (!generatedSlides || !mediaUrl) return;
    updateCurrentSlide({
      ...generatedSlides[currentSlideIndex],
      customImage: mediaUrl
    });
    setMediaUrl('');
    setShowMediaInput(false);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file && generatedSlides) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        updateCurrentSlide({
           ...generatedSlides[currentSlideIndex],
           customImage: result
        });
        setShowMediaInput(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const addNewSlide = () => {
     if (!generatedSlides) return;
     const newSlide: SlideData = {
       title: "New Slide",
       content: ["Add your content here"],
       layout: "bullet_points" as any
     };
     const newSlides = [...generatedSlides];
     newSlides.splice(currentSlideIndex + 1, 0, newSlide);
     updateSlides(newSlides);
     setCurrentSlideIndex(currentSlideIndex + 1);
  };

  const addTextToSlide = () => {
    if (!generatedSlides) return;
    const current = generatedSlides[currentSlideIndex];
    const newContent = [...current.content, "New Text Block"];
    updateCurrentSlide({ ...current, content: newContent });
  };

  const toggleMenu = (menu: typeof activeMenu) => {
    setActiveMenu(prev => prev === menu ? 'none' : menu);
  };

  // --- EDITOR VIEW ---
  if (generatedSlides) {
    return (
      <div className="h-screen w-full bg-[#0B0F17] flex flex-col text-white font-sans overflow-hidden">
        {/* Header */}
        <header className="h-14 border-b border-slate-800/60 bg-[#0B0F17] flex items-center justify-between px-2 md:px-4 shrink-0 z-50 relative shadow-md">
            <div className="flex items-center gap-2 md:gap-4 overflow-hidden">
               <button onClick={goHome} className="flex items-center text-slate-400 hover:text-white transition-colors text-xs font-medium gap-1 uppercase tracking-wide shrink-0">
                 <ArrowLeft size={14} /> <span className="hidden sm:inline">Back</span>
               </button>
               <div className="h-4 w-px bg-slate-800 shrink-0"></div>
               <h1 className="font-bold text-sm md:text-lg truncate max-w-[100px] md:max-w-[300px] text-slate-200">{query || "Untitled"}</h1>
            </div>

            {/* Top Right Controls */}
            <div className="flex items-center gap-1 md:gap-2">

               {/* Mobile Menu Toggle for Controls if screen is small? No, keep main controls visible, maybe icon only */}

               {/* THEMES */}
               <div className="relative">
                 <button 
                   onClick={() => toggleMenu('themes')}
                   className={`flex items-center gap-2 px-2 md:px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${activeMenu === 'themes' ? 'bg-blue-600 text-white' : 'text-slate-300 hover:bg-slate-800'}`}
                   title="Themes"
                 >
                   <Palette size={16} /> <span className="hidden md:inline">Themes</span>
                 </button>
                 {activeMenu === 'themes' && (
                    <div className="absolute top-full right-0 mt-2 w-[300px] md:w-[500px] h-[400px] md:h-[500px] glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in border border-slate-700 flex flex-col">
                      <div className="p-3 border-b border-white/10 flex justify-between items-center bg-slate-900/50">
                        <span className="text-xs font-bold text-slate-400 uppercase">Design & Theme</span>
                        <X size={14} className="cursor-pointer text-slate-500 hover:text-white" onClick={() => setActiveMenu('none')} />
                      </div>
                      <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-6">
                        {THEME_CATEGORIES.map((cat, i) => (
                          <div key={i}>
                            <h4 className="text-xs font-bold text-blue-400 mb-3 uppercase tracking-wider">{cat.category}</h4>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                              {cat.items.map(t => (
                                <button 
                                  key={t.id}
                                  onClick={() => setCurrentTheme(t)}
                                  className={`group relative p-3 rounded-lg border text-left transition-all ${currentTheme.id === t.id ? 'border-blue-500 bg-slate-800' : 'border-slate-700 bg-slate-800/50 hover:bg-slate-800'}`}
                                >
                                  <div className="flex items-center justify-between mb-2">
                                    <span className="font-semibold text-sm text-slate-200">{t.name}</span>
                                    {currentTheme.id === t.id && <div className="w-2 h-2 rounded-full bg-blue-500"></div>}
                                  </div>
                                  <div className="flex gap-1.5">
                                    <div className="w-4 h-4 rounded-full border border-white/10" style={{ background: t.textPrimary }}></div>
                                    <div className="w-4 h-4 rounded-full border border-white/10" style={{ background: t.cardBg === 'transparent' ? '#000' : t.cardBg }}></div>
                                    <div className="w-4 h-4 rounded-full border border-white/10" style={{ background: t.accentColor }}></div>
                                  </div>
                                </button>
                              ))}
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                 )}
               </div>

               {/* ANIMATIONS */}
               <div className="relative hidden sm:block">
                 <button 
                   onClick={() => toggleMenu('animations')}
                   className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${activeMenu === 'animations' ? 'bg-blue-600 text-white' : 'text-slate-300 hover:bg-slate-800'}`}
                 >
                   <Move size={16} /> <span className="hidden lg:inline">Animations</span>
                 </button>
                 {activeMenu === 'animations' && (
                    <div className="absolute top-full right-0 mt-2 w-[300px] md:w-[400px] h-[500px] glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in border border-slate-700 flex flex-col">
                      <div className="p-3 border-b border-white/10 flex justify-between items-center bg-slate-900/50">
                        <span className="text-xs font-bold text-slate-400 uppercase">Element Entrances</span>
                        <X size={14} className="cursor-pointer text-slate-500 hover:text-white" onClick={() => setActiveMenu('none')} />
                      </div>
                      <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-6">
                         {ANIMATION_CATEGORIES.map((cat, i) => (
                           <div key={i}>
                             <h4 className="text-[10px] font-bold text-indigo-400 mb-2 uppercase">{cat.category}</h4>
                             <div className="grid grid-cols-2 gap-2">
                               {cat.items.map(t => (
                                 <button
                                   key={t.id}
                                   onClick={() => setAnimType(t.id)}
                                   className={`px-3 py-2 rounded text-xs text-left border transition-all ${animType === t.id ? 'bg-blue-600 border-blue-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-300 hover:border-slate-500'}`}
                                 >
                                   {t.label}
                                 </button>
                               ))}
                             </div>
                           </div>
                         ))}
                      </div>
                      {/* Speed/Delay controls */}
                      <div className="p-3 border-t border-white/10 bg-slate-900/80">
                         <div className="flex gap-4">
                           <div className="flex-1">
                             <div className="text-[10px] text-slate-500 mb-1 uppercase font-bold">Speed</div>
                             <select 
                                value={animSpeed} 
                                onChange={(e) => setAnimSpeed(e.target.value)}
                                className="w-full bg-slate-800 text-xs text-slate-300 border border-slate-700 rounded p-1 outline-none"
