                               {ANIMATION_SPEEDS.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                             </select>
                           </div>
                           <div className="flex-1">
                             <div className="text-[10px] text-slate-500 mb-1 uppercase font-bold">Delay</div>
                             <select 
                                value={animDelay} 
                                onChange={(e) => setAnimDelay(e.target.value)}
                                className="w-full bg-slate-800 text-xs text-slate-300 border border-slate-700 rounded p-1 outline-none"
                             >
                               {ANIMATION_DELAYS.map(d => <option key={d.id} value={d.id}>{d.label}</option>)}
                             </select>
                           </div>
                         </div>
                      </div>
                    </div>
                 )}
               </div>

               {/* TRANSITIONS */}
               <div className="relative hidden sm:block">
                 <button 
                   onClick={() => toggleMenu('transitions')}
                   className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${activeMenu === 'transitions' ? 'bg-blue-600 text-white' : 'text-slate-300 hover:bg-slate-800'}`}
                 >
                   <Layers size={16} /> <span className="hidden lg:inline">Transitions</span>
                 </button>
                 {/* ... Transitions Dropdown ... */}
                 {activeMenu === 'transitions' && (
                    <div className="absolute top-full right-0 mt-2 w-[300px] h-[500px] glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in border border-slate-700 flex flex-col">
                      <div className="p-3 border-b border-white/10 flex justify-between items-center bg-slate-900/50">
                        <span className="text-xs font-bold text-slate-400 uppercase">Slide Transitions</span>
