                         {ANIMATION_CATEGORIES.slice(0,3).map((cat, i) => (
                           <div key={i}>
                             <h4 className="text-[10px] font-bold text-emerald-400 mb-2 uppercase">{cat.category}</h4>
                             <div className="grid grid-cols-2 gap-2">
                               {cat.items.map(t => (
                                 <button
                                   key={t.id}
                                   onClick={() => setAnimType(t.id)} 
                                   className={`px-3 py-2 rounded text-xs text-left border transition-all ${animType === t.id ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-300 hover:border-slate-500'}`}
                                 >
                                   {t.label}
                                 </button>
                               ))}
                             </div>
                           </div>
                         ))}
                      </div>
                    </div>
                 )}
               </div>

               {/* SETTINGS */}
               <div className="relative">
                  <button 
                    onClick={() => toggleMenu('settings')}
                    className={`p-2 rounded-md transition-colors ${activeMenu === 'settings' ? 'text-blue-400 bg-slate-800' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
                  >
                     <Settings size={18} />
                  </button>
                  {activeMenu === 'settings' && (
                    <div className="absolute top-full right-0 mt-2 w-72 glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in border border-slate-700">
                       <div className="p-3 border-b border-white/10 bg-slate-900/50">
                          <span className="text-xs font-bold text-slate-400 uppercase">General Settings</span>
                       </div>
                       <div className="p-4">
