function App() {
  const [query, setQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedSlides, setGeneratedSlides] = useState<SlideData[] | null>(null);
  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);
  const [error, setError] = useState<string | null>(null);

  // Appearance State
  const [currentTheme, setCurrentTheme] = useState<Theme>(THEME_CATEGORIES[0].items[0]);

  // Animation State
  const [animType, setAnimType] = useState('type-slide-up');
  const [animSpeed, setAnimSpeed] = useState('speed-normal');
  const [animDelay, setAnimDelay] = useState('delay-none');

  // Settings
  const [autoAdvance, setAutoAdvance] = useState(false);

  // Derived animation class
  const currentAnimationClass = `anim-base ${animType} ${animSpeed} ${animDelay}`;

  // UI Toggles
  const [activeMenu, setActiveMenu] = useState<'none' | 'design' | 'settings'>('none');
  const [designTab, setDesignTab] = useState<'themes' | 'animations' | 'transitions'>('themes');

  const [showChat, setShowChat] = useState(false);
  const [showMediaInput, setShowMediaInput] = useState(false);

  // Responsive UI States
  const [showLeftSidebar, setShowLeftSidebar] = useState(true);

  // Scaling State
  const canvasRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(1);

  const [mediaUrl, setMediaUrl] = useState('');
  const [isPlaying, setIsPlaying] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const autoPlayRef = useRef<number | null>(null);

  // Handle Resize for Scaling
  useEffect(() => {
    const handleResize = () => {
      if (!canvasRef.current) return;
      const { width, height } = canvasRef.current.getBoundingClientRect();
      const targetWidth = 1280;
      const targetHeight = 720;

      const widthRatio = (width - 60) / targetWidth; // Padding buffer
      const heightRatio = (height - 60) / targetHeight;

      // Use the smaller ratio to ensure it fits entirely
      const newScale = Math.min(widthRatio, heightRatio);
      setScale(Math.max(0.1, newScale)); // Prevent scale 0
    };

    // Initial calc
    handleResize();

    // Resize listener
    window.addEventListener('resize', handleResize);

    // Adjust sidebars on mobile
    if (window.innerWidth < 1024) {
      setShowLeftSidebar(false);
    }

    return () => window.removeEventListener('resize', handleResize);
  }, [generatedSlides, showLeftSidebar]);

  // Auto Play Logic
  useEffect(() => {
    const shouldPlay = isPlaying || autoAdvance;

    if (shouldPlay && generatedSlides) {
      autoPlayRef.current = window.setInterval(() => {
        setCurrentSlideIndex(prev => {
           if (prev < generatedSlides.length - 1) {
             return prev + 1;
           } else {
             if (isPlaying) setIsPlaying(false);
             return prev; 
           }
        });
      }, 3000); 
    } else {
      if (autoPlayRef.current) window.clearInterval(autoPlayRef.current);
    }
    return () => {
      if (autoPlayRef.current) window.clearInterval(autoPlayRef.current);
    };
  }, [isPlaying, autoAdvance, generatedSlides]);

  const handleGenerate = async () => {
    if (!query.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const slides = await generatePresentationContent(query);
      setGeneratedSlides(slides);
      setCurrentSlideIndex(0);
      // Auto-hide sidebars on mobile after generation to focus on content
      if (window.innerWidth < 1024) {
        setShowLeftSidebar(false);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unexpected error occurred.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleGenerate();
  };

  const goHome = () => {
    setGeneratedSlides(null);
    setQuery('');
    setError(null);
    setShowChat(false);
    setIsPlaying(false);
    setActiveMenu('none');
  };

  const nextSlide = () => setCurrentSlideIndex(prev => Math.min(prev + 1, (generatedSlides?.length || 1) - 1));
  const prevSlide = () => setCurrentSlideIndex(prev => Math.max(prev - 1, 0));

  const updateSlides = (newSlides: SlideData[]) => {
    setGeneratedSlides(newSlides);
    if (currentSlideIndex >= newSlides.length) {
      setCurrentSlideIndex(Math.max(0, newSlides.length - 1));
    }
  };

  const updateCurrentSlide = (updatedSlide: SlideData) => {
    if (!generatedSlides) return;
    const newSlides = [...generatedSlides];
    newSlides[currentSlideIndex] = updatedSlide;
    setGeneratedSlides(newSlides);
  };

  const handleInsertMediaUrl = () => {
    if (!generatedSlides || !mediaUrl) return;
    updateCurrentSlide({
      ...generatedSlides[currentSlideIndex],
      customImage: mediaUrl
    });
    setMediaUrl('');
    setShowMediaInput(false);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file && generatedSlides) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        updateCurrentSlide({
           ...generatedSlides[currentSlideIndex],
           customImage: result
        });
        setShowMediaInput(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const addNewSlide = () => {
     if (!generatedSlides) return;
     const newSlide: SlideData = {
       title: "New Slide",
       content: ["Add your content here"],
       layout: "bullet_points" as any
     };
     const newSlides = [...generatedSlides];
     newSlides.splice(currentSlideIndex + 1, 0, newSlide);
     updateSlides(newSlides);
     setCurrentSlideIndex(currentSlideIndex + 1);
  };

  const addTextToSlide = () => {
    if (!generatedSlides) return;
    const current = generatedSlides[currentSlideIndex];
    const newContent = [...current.content, "New Text Block"];
    updateCurrentSlide({ ...current, content: newContent });
  };

  const toggleMenu = (menu: typeof activeMenu) => {
    setActiveMenu(prev => prev === menu ? 'none' : menu);
  };

  // --- EDITOR VIEW ---
  if (generatedSlides) {
    return (
      <div className="h-screen w-full bg-[#0B0F17] flex flex-col text-white font-sans overflow-hidden">
        {/* Header - Cleaned up to match reference */}
        <header className="h-14 border-b border-white/5 bg-[#0B0F17] flex items-center justify-between px-4 shrink-0 z-50 relative">
            <div className="flex items-center gap-4">
               <button onClick={goHome} className="flex items-center text-slate-400 hover:text-white transition-colors text-sm font-medium gap-2">
                 <ChevronLeft size={16} /> Back
               </button>
               <h1 className="font-bold text-base text-white">{query || "Untitled Presentation"}</h1>
            </div>

            {/* Top Right Controls */}
            <div className="flex items-center gap-2">

               {/* GeniusBot */}
               <button 
                 onClick={() => setShowChat(!showChat)}
                 className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${showChat ? 'bg-blue-500/10 text-blue-400' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
               >
                 <Sparkles size={16} /> <span>GeniusBot</span>
               </button>

               <div className="w-px h-4 bg-white/10 mx-1"></div>

               {/* PDF (Export) */}
               <button className="flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-medium text-slate-400 hover:text-white hover:bg-white/5 transition-all">
                 <Download size={16} /> <span>PDF</span>
               </button>

               {/* Settings */}
               <div className="relative">
                 <button 
                    onClick={() => toggleMenu('settings')}
                    className={`p-2 rounded-lg transition-colors ${activeMenu === 'settings' ? 'bg-white/10 text-white' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                 >
                    <Settings size={18} />
                 </button>
                 {activeMenu === 'settings' && (
                    <div className="absolute top-full right-0 mt-2 w-72 glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in border border-slate-700">
                       <div className="p-4">
                          <h4 className="text-xs font-bold text-slate-400 uppercase mb-4">Presentation Settings</h4>
                          <div className="flex items-center justify-between">
                             <span className="text-sm text-white">Auto-Advance</span>
                             <button 
                               onClick={() => setAutoAdvance(!autoAdvance)}
                               className={`w-10 h-5 rounded-full relative transition-colors ${autoAdvance ? 'bg-blue-600' : 'bg-slate-600'}`}
                             >
                                <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${autoAdvance ? 'left-6' : 'left-1'}`}></div>
                             </button>
                          </div>
                       </div>
                    </div>
                  )}
               </div>

               {/* Design/Grid Menu (Consolidated) */}
               <div className="relative">
                 <button 
                    onClick={() => toggleMenu('design')}
                    className={`p-2 rounded-lg transition-colors ${activeMenu === 'design' ? 'bg-white/10 text-white' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                 >
                    <LayoutGrid size={18} />
                 </button>
                 {activeMenu === 'design' && (
                    <div className="absolute top-full right-0 mt-2 w-[480px] h-[550px] glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in border border-slate-700 flex flex-col">
                       {/* Tabs */}
                       <div className="flex border-b border-white/10">
                          <button onClick={() => setDesignTab('themes')} className={`flex-1 py-3 text-xs font-bold uppercase transition-colors ${designTab === 'themes' ? 'text-blue-400 border-b-2 border-blue-400 bg-white/5' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>Themes</button>
                          <button onClick={() => setDesignTab('animations')} className={`flex-1 py-3 text-xs font-bold uppercase transition-colors ${designTab === 'animations' ? 'text-blue-400 border-b-2 border-blue-400 bg-white/5' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>Animations</button>
                          <button onClick={() => setDesignTab('transitions')} className={`flex-1 py-3 text-xs font-bold uppercase transition-colors ${designTab === 'transitions' ? 'text-blue-400 border-b-2 border-blue-400 bg-white/5' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>Transitions</button>
                       </div>

                       {/* Content */}
                       <div className="flex-1 overflow-y-auto custom-scrollbar p-4">
                          {designTab === 'themes' && (
                             <div className="space-y-6">
                                {THEME_CATEGORIES.map((cat, i) => (
                                  <div key={i}>
                                    <h4 className="text-xs font-bold text-slate-500 mb-3 uppercase tracking-wider">{cat.category}</h4>
                                    <div className="grid grid-cols-2 gap-3">
                                      {cat.items.map(t => (
                                        <button 
                                          key={t.id}
                                          onClick={() => setCurrentTheme(t)}
                                          className={`group relative p-3 rounded-lg border text-left transition-all ${currentTheme.id === t.id ? 'border-blue-500 bg-blue-500/10' : 'border-slate-700 bg-slate-800/50 hover:border-slate-500'}`}
                                        >
                                          <div className="flex items-center justify-between mb-2">
                                            <span className="font-semibold text-sm text-slate-200">{t.name}</span>
                                            {currentTheme.id === t.id && <div className="w-1.5 h-1.5 rounded-full bg-blue-500"></div>}
                                          </div>
                                          <div className="flex gap-1.5">
                                            <div className="w-3 h-3 rounded-full border border-white/10" style={{ background: t.textPrimary }}></div>
                                            <div className="w-3 h-3 rounded-full border border-white/10" style={{ background: t.cardBg === 'transparent' ? '#000' : t.cardBg }}></div>
                                            <div className="w-3 h-3 rounded-full border border-white/10" style={{ background: t.accentColor }}></div>
                                          </div>
                                        </button>
                                      ))}
                                    </div>
                                  </div>
                                ))}
                             </div>
                          )}

                          {designTab === 'animations' && (
                             <div className="space-y-6">
                                <div className="p-3 bg-slate-800/50 rounded-lg border border-white/5 mb-4">
                                   <div className="flex gap-4">
                                     <div className="flex-1">
                                       <label className="text-[10px] text-slate-400 uppercase font-bold block mb-1.5">Speed</label>
                                       <select value={animSpeed} onChange={(e) => setAnimSpeed(e.target.value)} className="w-full bg-black/20 text-xs text-slate-300 border border-white/10 rounded p-1.5 outline-none">
                                         {ANIMATION_SPEEDS.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                                       </select>
                                     </div>
                                     <div className="flex-1">
                                       <label className="text-[10px] text-slate-400 uppercase font-bold block mb-1.5">Delay</label>
                                       <select value={animDelay} onChange={(e) => setAnimDelay(e.target.value)} className="w-full bg-black/20 text-xs text-slate-300 border border-white/10 rounded p-1.5 outline-none">
                                         {ANIMATION_DELAYS.map(d => <option key={d.id} value={d.id}>{d.label}</option>)}
                                       </select>
                                     </div>
                                   </div>
                                </div>
                                {ANIMATION_CATEGORIES.map((cat, i) => (
                                   <div key={i}>
                                     <h4 className="text-[10px] font-bold text-slate-500 mb-2 uppercase">{cat.category}</h4>
                                     <div className="grid grid-cols-2 gap-2">
                                       {cat.items.map(t => (
                                         <button
                                           key={t.id}
                                           onClick={() => setAnimType(t.id)}
                                           className={`px-3 py-2 rounded text-xs text-left border transition-all ${animType === t.id ? 'bg-blue-600 border-blue-500 text-white' : 'bg-slate-800/50 border-slate-700 text-slate-300 hover:border-slate-500'}`}
                                         >
                                           {t.label}
                                         </button>
                                       ))}
                                     </div>
                                   </div>
                                 ))}
                             </div>
                          )}

                          {designTab === 'transitions' && (
                             <div className="space-y-6">
                                {ANIMATION_CATEGORIES.slice(0,3).map((cat, i) => (
                                   <div key={i}>
                                     <h4 className="text-[10px] font-bold text-slate-500 mb-2 uppercase">{cat.category}</h4>
                                     <div className="grid grid-cols-2 gap-2">
                                       {cat.items.map(t => (
                                         <button
                                           key={t.id}
                                           onClick={() => setAnimType(t.id)}
                                           className={`px-3 py-2 rounded text-xs text-left border transition-all ${animType === t.id ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-slate-800/50 border-slate-700 text-slate-300 hover:border-slate-500'}`}
                                         >
                                           {t.label}
                                         </button>
                                       ))}
                                     </div>
                                   </div>
                                 ))}
                             </div>
                          )}
                       </div>
                    </div>
                 )}
               </div>

               {/* Present Button */}
               <button 
                 onClick={() => setIsPlaying(!isPlaying)}
                 className={`ml-2 bg-blue-600 hover:bg-blue-500 text-white px-4 py-1.5 rounded-lg text-sm font-semibold flex items-center gap-2 transition-all hover:scale-105 shadow-lg shadow-blue-900/20 ${isPlaying ? 'ring-2 ring-white/20' : ''}`}
               >
                 {isPlaying ? <Pause size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />} 
                 <span>{isPlaying ? 'Presenting' : 'Present'}</span>
               </button>
            </div>
        </header>

        {showChat && (
          <ChatAssistant 
            currentSlides={generatedSlides} 
            onUpdateSlides={updateSlides}
            onClose={() => setShowChat(false)}
          />
        )}

        {/* Insert Media Popover */}
        {showMediaInput && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in p-4">
             <div className="glass-panel p-6 rounded-xl w-full max-w-[400px] shadow-2xl animate-bounce-in border border-slate-700 relative">
                <button onClick={() => setShowMediaInput(false)} className="absolute top-4 right-4 text-slate-400 hover:text-white"><X size={18}/></button>
                <h4 className="text-xl font-bold text-white mb-6">Insert Media</h4>

                <div className="space-y-6">
                  <div className="border-2 border-dashed border-slate-700 rounded-lg p-6 flex flex-col items-center justify-center hover:border-blue-500 hover:bg-slate-800/30 transition-all cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
                     <Upload size={32} className="text-slate-500 group-hover:text-blue-400 mb-2" />
                     <span className="text-sm text-slate-300 font-medium">Upload from Device</span>
                     <span className="text-xs text-slate-500 mt-1">JPG, PNG, GIF up to 5MB</span>
                     <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
                  </div>
                  <div className="relative flex py-2 items-center">
                    <div className="flex-grow border-t border-slate-700"></div>
                    <span className="flex-shrink-0 mx-4 text-slate-500 text-xs uppercase">Or via URL</span>
                    <div className="flex-grow border-t border-slate-700"></div>
                  </div>
                  <div>
                    <div className="flex items-center gap-2 bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 focus-within:border-blue-500 transition-colors">
                      <Globe size={16} className="text-slate-500" />
                      <input type="text" value={mediaUrl} onChange={(e) => setMediaUrl(e.target.value)} placeholder="https://example.com/image.jpg" className="flex-1 bg-transparent text-sm text-white outline-none" />
                    </div>
                    <button onClick={handleInsertMediaUrl} disabled={!mediaUrl} className="w-full mt-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white py-2 rounded-lg font-medium transition-colors">Insert from URL</button>
                  </div>
                </div>
             </div>
          </div>
        )}

        {/* Main Workspace */}
        <div className="flex-1 flex overflow-hidden relative">

           {/* Left Sidebar - Slides */}
           <div className={`
             absolute md:relative z-20 h-full w-64 flex flex-col border-r border-slate-800 bg-[#0B0F17] shrink-0 transform transition-transform duration-300
             ${showLeftSidebar ? 'translate-x-0' : '-translate-x-full md:hidden'}
           `}>
              <div className="p-4 flex items-center justify-between border-b border-slate-800/50">
                 <span className="text-[11px] font-bold text-slate-500 tracking-widest uppercase">SLIDES</span>
                 <button onClick={addNewSlide} className="text-slate-400 hover:text-white transition-colors" title="Add New Slide"><Plus size={16} /></button>
                 <button onClick={() => setShowLeftSidebar(false)} className="md:hidden text-slate-400"><X size={16}/></button>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
                 {generatedSlides.map((slide, idx) => (
                    <div 
                      key={idx}
                      onClick={() => { setCurrentSlideIndex(idx); if(window.innerWidth < 768) setShowLeftSidebar(false); }}
                      className="group flex gap-3 cursor-pointer"
                    >
                       <span className={`text-[10px] font-medium mt-1 ${idx === currentSlideIndex ? 'text-blue-500' : 'text-slate-600'}`}>
                         {idx + 1}
                       </span>
                       <div className={`
                         flex-1 aspect-video rounded border-2 relative overflow-hidden transition-all duration-200 bg-slate-900
                         ${idx === currentSlideIndex ? 'border-blue-600 shadow-[0_0_0_1px_rgba(37,99,235,0.5)]' : 'border-slate-800 hover:border-slate-700 opacity-70 hover:opacity-100'}
                       `}>
                          {/* Mini Thumbnail content preview */}
                          <div className="w-full h-full p-1.5 flex flex-col items-start justify-center pointer-events-none opacity-50">
                             <div className="w-3/4 h-0.5 bg-slate-600 rounded mb-0.5"></div>
                             <div className="w-1/2 h-0.5 bg-slate-700 rounded mb-1"></div>
                             <div className="w-full h-px bg-slate-800 rounded"></div>
                          </div>
                       </div>
                    </div>
                 ))}
              </div>
           </div>

           {/* Center Canvas */}
           <div ref={canvasRef} className="flex-1 bg-[#05080F] relative flex flex-col items-center justify-center overflow-hidden">

               {/* Mobile Sidebar Toggle */}
               <button onClick={() => setShowLeftSidebar(true)} className={`absolute top-4 left-4 p-2 text-slate-500 bg-slate-900 rounded-md md:hidden z-10 ${showLeftSidebar ? 'hidden' : 'block'}`}>
                  <Sidebar size={18} />
               </button>

               {/* Add Content Overlay Controls (Top Right of Canvas Area) */}
               <div className="absolute top-6 right-6 z-30 flex gap-2">
                  <button onClick={addTextToSlide} className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-slate-800/80 hover:bg-slate-700 text-xs font-medium text-slate-300 border border-white/5 transition-colors">
                     <Type size={12} /> Add Text
                  </button>
                  <button onClick={() => setShowMediaInput(true)} className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-slate-800/80 hover:bg-slate-700 text-xs font-medium text-slate-300 border border-white/5 transition-colors">
                     <ImageIcon size={12} /> Media
                  </button>
               </div>

               {/* Scaled Slide Container */}
               <div className="relative">
                 <div 
                    style={{ 
                      width: '1280px', 
                      height: '720px', 
                      transform: `scale(${scale})`,
                    }}
                    className="shadow-2xl overflow-hidden bg-black rounded-lg" // Removed border/ring for cleaner look
                  >
                     <div key={`${currentSlideIndex}-${currentAnimationClass}`} className="w-full h-full">
                        <SlideRenderer 
                          slide={generatedSlides[currentSlideIndex]} 
                          theme={currentTheme} 
                          animationClass={currentAnimationClass}
                          onUpdate={updateCurrentSlide}
                        />
                     </div>
                  </div>
               </div>

               {/* Floating Bottom Navigation */}
               <div className="absolute bottom-6 z-40 flex items-center justify-center">
                  <div className="flex items-center gap-1 bg-[#0F131C] border border-white/10 rounded-full p-1 shadow-lg">
                     <button 
                       onClick={prevSlide}
                       disabled={currentSlideIndex === 0}
                       className="p-2 rounded-full hover:bg-white/10 text-slate-400 hover:text-white disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
                     >
                       <ChevronLeft size={16} />
                     </button>
                     <span className="text-xs font-mono text-slate-300 font-medium px-2 min-w-[50px] text-center">
                       {currentSlideIndex + 1} / {generatedSlides.length}
                     </span>
                     <button 
                       onClick={nextSlide}
                       disabled={currentSlideIndex === generatedSlides.length - 1}
                       className="p-2 rounded-full hover:bg-white/10 text-slate-400 hover:text-white disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
                     >
                       <ChevronRight size={16} />
                     </button>
                  </div>
               </div>
           </div>
        </div>
      </div>
    );
  }

  // --- VIEW: HOME ---
  return (
    <div className="relative min-h-screen w-full overflow-hidden flex flex-col items-center justify-center">
      <StarBackground />
      {/* (Home Screen Content) */}
      <div className="absolute top-4 left-4 md:top-8 md:left-8 z-10 flex flex-col">
        <span className="text-[8px] md:text-[10px] uppercase tracking-[0.2em] text-slate-400 font-bold mb-1">Presented by</span>
        <div className="flex items-center gap-2">
            <div className="h-4 w-1 md:h-6 bg-blue-500 rounded-full"></div>
            <span className="text-lg md:text-2xl font-black tracking-widest text-white">NEXZI</span>
        </div>
      </div>

      <div className="relative z-10 flex flex-col items-center max-w-4xl w-full px-4 text-center">
        <div className="mb-4 md:mb-8 inline-flex items-center gap-2 px-3 py-1 md:px-4 md:py-1.5 rounded-full border border-blue-500/30 bg-blue-950/30 backdrop-blur-md shadow-[0_0_20px_rgba(59,130,246,0.3)] animate-float">
          <Sparkles className="w-3 h-3 md:w-4 md:h-4 text-blue-400" />
          <span className="text-xs md:text-sm font-semibold text-blue-100">OrbitSlide AI 3.0</span>
        </div>
        <h1 className="text-4xl sm:text-6xl md:text-8xl font-black tracking-tight leading-[1.1] mb-2">Roar into</h1>
        <h1 className="text-4xl sm:text-6xl md:text-8xl font-black tracking-tight leading-[1.1] mb-6 md:mb-8 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 via-cyan-400 to-blue-500 glow-text">Greatness.</h1>
        <p className="max-w-2xl text-sm md:text-xl text-slate-300 font-light leading-relaxed mb-8 md:mb-12 opacity-90 px-4">Unleash the power of AI to create professional slide decks instantly.</p>

        <div className="w-full max-w-2xl relative group px-4">
          <div className="absolute inset-0 bg-gradient-to-r from-blue-600 to-cyan-600 rounded-xl opacity-40 blur-lg group-hover:opacity-60 transition duration-500"></div>
          <div className="relative flex items-center bg-[#0B1221] border border-blue-500/30 rounded-xl p-2 shadow-2xl">
            <div className="pl-2 md:pl-4 pr-2 md:pr-3 text-slate-400"><Sparkles className="w-4 h-4 md:w-5 md:h-5 text-blue-400" /></div>
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={handleKeyDown}
              disabled={isGenerating}
              placeholder="What do you want to create?"
              className="flex-1 bg-transparent text-white placeholder-slate-500 outline-none text-sm md:text-lg py-2 md:py-3 font-medium"
            />
            <button 
              onClick={handleGenerate}
              disabled={!query.trim() || isGenerating}
              className={`p-2 md:p-3 rounded-lg flex items-center justify-center transition-all duration-300 ${query.trim() && !isGenerating ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg shadow-blue-900/50' : 'bg-slate-800 text-slate-500 cursor-not-allowed'}`}
            >
              {isGenerating ? <div className="w-4 h-4 md:w-5 md:h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : <ArrowRight className="w-4 h-4 md:w-5 md:h-5" />}
            </button>
          </div>
        </div>

        <div className="mt-8 flex flex-wrap items-center justify-center gap-2 md:gap-3 text-xs md:text-sm text-slate-400">
          <span className="flex items-center gap-2 opacity-70">
            <div className="border border-slate-600 rounded px-1.5 py-0.5 text-[10px]">Generate</div>
            Start from Scratch
          </span>
          <span className="mx-1 md:mx-2 text-slate-700">•</span>
          <span className="opacity-70">Try:</span>
          {SUGGESTIONS.map((s, i) => (
            <button key={i} onClick={() => setQuery(s)} className="hover:text-blue-400 hover:underline transition-colors hidden sm:inline-block">{s}</button>
          ))}
          <button onClick={() => setQuery(SUGGESTIONS[0])} className="hover:text-blue-400 hover:underline transition-colors sm:hidden">Example Topic</button>
        </div>
        {error && <div className="mt-6 bg-red-500/10 border border-red-500/50 text-red-200 px-4 py-2 rounded-lg flex items-center gap-2 animate-pulse text-sm"><X size={16} /> {error}</div>}
      </div>
      <div className="absolute top-1/2 left-[15%] w-[30vw] h-[30vw] border border-blue-500/10 rounded-full -translate-y-1/2 pointer-events-none"></div>
      <div className="absolute top-1/2 right-[15%] w-[30vw] h-[30vw] border border-blue-500/10 rounded-full -translate-y-1/2 pointer-events-none"></div>
    </div>
  );
}

export default App;

import React, { useState, useRef, useEffect } from 'react';
import StarBackground from './components/StarBackground';
