const SUGGESTIONS = [
  "Future of AI",
  "Cybersecurity",
  "Sustainable Energy",
  "Digital Marketing Strategy"
];

function App() {
  const [query, setQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedSlides, setGeneratedSlides] = useState<SlideData[] | null>(null);
  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);
  const [error, setError] = useState<string | null>(null);

  // Appearance State
  const [currentTheme, setCurrentTheme] = useState<Theme>(THEME_CATEGORIES[0].items[0]);

  // Animation State
  const [animType, setAnimType] = useState('type-slide-up');
  const [animSpeed, setAnimSpeed] = useState('speed-normal');
  const [animDelay, setAnimDelay] = useState('delay-none');

  // Settings
  const [autoAdvance, setAutoAdvance] = useState(false);

  // Derived animation class
  const currentAnimationClass = `anim-base ${animType} ${animSpeed} ${animDelay}`;

  // UI Toggles
  const [activeMenu, setActiveMenu] = useState<'none' | 'design' | 'settings'>('none');
  const [designTab, setDesignTab] = useState<'themes' | 'animations' | 'transitions'>('themes');

  const [showChat, setShowChat] = useState(false);
  const [showMediaInput, setShowMediaInput] = useState(false);

  // Responsive UI States
  const [showLeftSidebar, setShowLeftSidebar] = useState(true);

  // Scaling State
  const canvasRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(1);

  const [mediaUrl, setMediaUrl] = useState('');
  const [isPlaying, setIsPlaying] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const autoPlayRef = useRef<number | null>(null);

  // Sidebar thumbnail scaling
  const sidebarWidth = 256; // w-64 is 16rem = 256px
  const sidebarPadding = 32; // p-4 is 1rem = 16px * 2
  const thumbnailWidth = sidebarWidth - sidebarPadding;
  const thumbnailScale = thumbnailWidth / 1280;
  const thumbnailHeight = 720 * thumbnailScale;

  // Handle Resize for Scaling
  useEffect(() => {
    const handleResize = () => {
      if (!canvasRef.current) return;
      const { width, height } = canvasRef.current.getBoundingClientRect();
      const targetWidth = 1280;
      const targetHeight = 720;

      const widthRatio = (width - 60) / targetWidth; // Padding buffer
      const heightRatio = (height - 60) / targetHeight;

      // Use the smaller ratio to ensure it fits entirely
      const newScale = Math.min(widthRatio, heightRatio);
      setScale(Math.max(0.1, newScale)); // Prevent scale 0
    };

    // Initial calc
    handleResize();

    // Resize listener
    window.addEventListener('resize', handleResize);

    // Adjust sidebars on mobile
    if (window.innerWidth < 1024) {
      setShowLeftSidebar(false);
    }

    return () => window.removeEventListener('resize', handleResize);
  }, [generatedSlides, showLeftSidebar]);

  // Auto Play Logic
  useEffect(() => {
    const shouldPlay = isPlaying || autoAdvance;

    if (shouldPlay && generatedSlides) {
      autoPlayRef.current = window.setInterval(() => {
        setCurrentSlideIndex(prev => {
           if (prev < generatedSlides.length - 1) {
             return prev + 1;
           } else {
             if (isPlaying) setIsPlaying(false);
             return prev; 
           }
        });
      }, 3000); 
    } else {
      if (autoPlayRef.current) window.clearInterval(autoPlayRef.current);
    }
    return () => {
      if (autoPlayRef.current) window.clearInterval(autoPlayRef.current);
    };
  }, [isPlaying, autoAdvance, generatedSlides]);

  const handleGenerate = async () => {
    if (!query.trim()) return;
    setIsGenerating(true);
    setError(null);
    try {
      const slides = await generatePresentationContent(query);
      setGeneratedSlides(slides);
      setCurrentSlideIndex(0);
      // Auto-hide sidebars on mobile after generation to focus on content
      if (window.innerWidth < 1024) {
        setShowLeftSidebar(false); // Mobile defaults
      } else {
        setShowLeftSidebar(true); // Desktop defaults
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unexpected error occurred.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleGenerate();
  };

  const goHome = () => {
    setGeneratedSlides(null);
    setQuery('');
    setError(null);
    setShowChat(false);
    setIsPlaying(false);
    setActiveMenu('none');
  };

  const nextSlide = () => setCurrentSlideIndex(prev => Math.min(prev + 1, (generatedSlides?.length || 1) - 1));
  const prevSlide = () => setCurrentSlideIndex(prev => Math.max(prev - 1, 0));

  const updateSlides = (newSlides: SlideData[]) => {
    setGeneratedSlides(newSlides);
    if (currentSlideIndex >= newSlides.length) {
      setCurrentSlideIndex(Math.max(0, newSlides.length - 1));
    }
  };

  const updateCurrentSlide = (updatedSlide: SlideData) => {
    if (!generatedSlides) return;
    const newSlides = [...generatedSlides];
    newSlides[currentSlideIndex] = updatedSlide;
    setGeneratedSlides(newSlides);
  };

  const handleInsertMediaUrl = () => {
    if (!generatedSlides || !mediaUrl) return;
    updateCurrentSlide({
      ...generatedSlides[currentSlideIndex],
      customImage: mediaUrl
    });
    setMediaUrl('');
    setShowMediaInput(false);
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file && generatedSlides) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        updateCurrentSlide({
           ...generatedSlides[currentSlideIndex],
           customImage: result
        });
        setShowMediaInput(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const addNewSlide = () => {
     if (!generatedSlides) return;
     const newSlide: SlideData = {
       title: "New Slide",
       content: ["Add your content here"],
       layout: "bullet_points" as any
     };
     const newSlides = [...generatedSlides];
     newSlides.splice(currentSlideIndex + 1, 0, newSlide);
     updateSlides(newSlides);
     setCurrentSlideIndex(currentSlideIndex + 1);
  };

  const addTextToSlide = () => {
    if (!generatedSlides) return;
    const current = generatedSlides[currentSlideIndex];
    const newContent = [...current.content, "New Text Block"];
    updateCurrentSlide({ ...current, content: newContent });
  };

  const toggleMenu = (menu: typeof activeMenu) => {
    setActiveMenu(prev => prev === menu ? 'none' : menu);
  };

  // --- EDITOR VIEW ---
  if (generatedSlides) {
    return (
      <div className="h-screen w-full bg-[#0B0F17] flex flex-col text-white font-sans overflow-hidden">
        {/* Header - Pro Look */}
        <header className="h-16 border-b border-white/10 bg-[#0B0F17] flex items-center justify-between px-6 shrink-0 z-50 relative shadow-md">
            <div className="flex items-center gap-4">
               <button onClick={goHome} className="flex items-center text-slate-400 hover:text-white transition-colors text-sm font-medium gap-2 group">
                 <div className="p-1 rounded-full group-hover:bg-white/10 transition-colors">
                    <ChevronLeft size={18} />
                 </div>
                 <span className="font-semibold tracking-tight">Back</span>
               </button>
               <div className="h-6 w-px bg-white/10"></div>
               <h1 className="font-bold text-lg text-white tracking-tight">{query || "Untitled Presentation"}</h1>
            </div>

            {/* Top Right Controls */}
            <div className="flex items-center gap-3">

               {/* GeniusBot */}
               <button 
                 onClick={() => setShowChat(!showChat)}
                 className={`flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium transition-all ${showChat ? 'bg-indigo-500/10 text-indigo-400 border border-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5 border border-transparent'}`}
               >
                 <Sparkles size={16} /> <span>GeniusBot</span>
               </button>

               {/* PDF (Export) */}
               <button className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium text-slate-400 hover:text-white hover:bg-white/5 transition-all">
                 <Download size={16} /> <span className="hidden sm:inline">PDF</span>
               </button>

               {/* Design/Grid Menu */}
               <div className="relative">
                 <button 
                    onClick={() => toggleMenu('design')}
                    className={`p-2 rounded-lg transition-colors ${activeMenu === 'design' ? 'bg-white/10 text-white' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                    title="Design Tools"
                 >
                    <LayoutGrid size={20} />
                 </button>
                 {activeMenu === 'design' && (
                    <div className="absolute top-full right-0 mt-2 w-[480px] h-[550px] glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in border border-slate-700 flex flex-col">
                       {/* Tabs */}
                       <div className="flex border-b border-white/10">
                          <button onClick={() => setDesignTab('themes')} className={`flex-1 py-3 text-xs font-bold uppercase transition-colors ${designTab === 'themes' ? 'text-blue-400 border-b-2 border-blue-400 bg-white/5' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>Themes</button>
                          <button onClick={() => setDesignTab('animations')} className={`flex-1 py-3 text-xs font-bold uppercase transition-colors ${designTab === 'animations' ? 'text-blue-400 border-b-2 border-blue-400 bg-white/5' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>Animations</button>
                          <button onClick={() => setDesignTab('transitions')} className={`flex-1 py-3 text-xs font-bold uppercase transition-colors ${designTab === 'transitions' ? 'text-blue-400 border-b-2 border-blue-400 bg-white/5' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>Transitions</button>
                       </div>

                       {/* Content */}
                       <div className="flex-1 overflow-y-auto custom-scrollbar p-4">
                          {designTab === 'themes' && (
                             <div className="space-y-6">
                                {THEME_CATEGORIES.map((cat, i) => (
                                  <div key={i}>
                                    <h4 className="text-xs font-bold text-slate-500 mb-3 uppercase tracking-wider">{cat.category}</h4>
                                    <div className="grid grid-cols-2 gap-3">
                                      {cat.items.map(t => (
                                        <button 
                                          key={t.id}
                                          onClick={() => setCurrentTheme(t)}
                                          className={`group relative p-3 rounded-lg border text-left transition-all ${currentTheme.id === t.id ? 'border-blue-500 bg-blue-500/10' : 'border-slate-700 bg-slate-800/50 hover:border-slate-500'}`}
                                        >
                                          <div className="flex items-center justify-between mb-2">
                                            <span className="font-semibold text-sm text-slate-200">{t.name}</span>
                                            {currentTheme.id === t.id && <div className="w-1.5 h-1.5 rounded-full bg-blue-500"></div>}
                                          </div>
                                          <div className="flex gap-1.5">
                                            <div className="w-3 h-3 rounded-full border border-white/10" style={{ background: t.textPrimary }}></div>
                                            <div className="w-3 h-3 rounded-full border border-white/10" style={{ background: t.cardBg === 'transparent' ? '#000' : t.cardBg }}></div>
                                            <div className="w-3 h-3 rounded-full border border-white/10" style={{ background: t.accentColor }}></div>
                                          </div>
                                        </button>
                                      ))}
                                    </div>
                                  </div>
                                ))}
                             </div>
                          )}

                          {designTab === 'animations' && (
                             <div className="space-y-6">
                                <div className="p-3 bg-slate-800/50 rounded-lg border border-white/5 mb-4">
                                   <div className="flex gap-4">
                                     <div className="flex-1">
                                       <label className="text-[10px] text-slate-400 uppercase font-bold block mb-1.5">Speed</label>
                                       <select value={animSpeed} onChange={(e) => setAnimSpeed(e.target.value)} className="w-full bg-black/20 text-xs text-slate-300 border border-white/10 rounded p-1.5 outline-none">
                                         {ANIMATION_SPEEDS.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                                       </select>
                                     </div>
                                     <div className="flex-1">
                                       <label className="text-[10px] text-slate-400 uppercase font-bold block mb-1.5">Delay</label>
                                       <select value={animDelay} onChange={(e) => setAnimDelay(e.target.value)} className="w-full bg-black/20 text-xs text-slate-300 border border-white/10 rounded p-1.5 outline-none">
                                         {ANIMATION_DELAYS.map(d => <option key={d.id} value={d.id}>{d.label}</option>)}
                                       </select>
                                     </div>
                                   </div>
                                </div>
                                {ANIMATION_CATEGORIES.map((cat, i) => (
                                   <div key={i}>
                                     <h4 className="text-[10px] font-bold text-slate-500 mb-2 uppercase">{cat.category}</h4>
                                     <div className="grid grid-cols-2 gap-2">
                                       {cat.items.map(t => (
                                         <button
                                           key={t.id}
                                           onClick={() => setAnimType(t.id)}
                                           className={`px-3 py-2 rounded text-xs text-left border transition-all ${animType === t.id ? 'bg-blue-600 border-blue-500 text-white' : 'bg-slate-800/50 border-slate-700 text-slate-300 hover:border-slate-500'}`}
                                         >
                                           {t.label}
                                         </button>
                                       ))}
                                     </div>
                                   </div>
                                 ))}
                             </div>
                          )}

                          {designTab === 'transitions' && (
                             <div className="space-y-6">
                                {ANIMATION_CATEGORIES.slice(0,3).map((cat, i) => (
                                   <div key={i}>
                                     <h4 className="text-[10px] font-bold text-slate-500 mb-2 uppercase">{cat.category}</h4>
                                     <div className="grid grid-cols-2 gap-2">
                                       {cat.items.map(t => (
                                         <button
                                           key={t.id}
                                           onClick={() => setAnimType(t.id)}
                                           className={`px-3 py-2 rounded text-xs text-left border transition-all ${animType === t.id ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-slate-800/50 border-slate-700 text-slate-300 hover:border-slate-500'}`}
                                         >
                                           {t.label}
                                         </button>
                                       ))}
                                     </div>
                                   </div>
                                 ))}
                             </div>
                          )}
                       </div>
                    </div>
                 )}
               </div>

               {/* Settings */}
               <div className="relative">
                 <button 
                    onClick={() => toggleMenu('settings')}
                    className={`p-2 rounded-lg transition-colors ${activeMenu === 'settings' ? 'bg-white/10 text-white' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}
                    title="Settings"
                 >
                    <Settings size={20} />
                 </button>
                 {activeMenu === 'settings' && (
                    <div className="absolute top-full right-0 mt-2 w-72 glass-panel rounded-lg shadow-xl overflow-hidden z-50 animate-fade-in border border-slate-700">
                       <div className="p-4">
                          <h4 className="text-xs font-bold text-slate-400 uppercase mb-4">Presentation Settings</h4>
                          <div className="flex items-center justify-between">
                             <span className="text-sm text-white">Auto-Advance</span>
                             <button 
                               onClick={() => setAutoAdvance(!autoAdvance)}
                               className={`w-10 h-5 rounded-full relative transition-colors ${autoAdvance ? 'bg-blue-600' : 'bg-slate-600'}`}
                             >
                                <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${autoAdvance ? 'left-6' : 'left-1'}`}></div>
                             </button>
                          </div>
                       </div>
                    </div>
                  )}
               </div>

               <div className="w-px h-6 bg-white/10 mx-2"></div>

               {/* Present Button */}
               <button 
                 onClick={() => setIsPlaying(!isPlaying)}
                 className={`bg-blue-600 hover:bg-blue-500 text-white px-5 py-2 rounded-lg text-sm font-semibold flex items-center gap-2 transition-all hover:scale-105 shadow-lg shadow-blue-900/30 ${isPlaying ? 'ring-2 ring-white/30' : ''}`}
