                                     <div className="flex gap-1 mt-1.5">
                                        <div className="w-2 h-2 rounded-full" style={{ background: t.accentColor }}></div>
                                        <div className="w-2 h-2 rounded-full border border-white/20" style={{ background: t.textPrimary }}></div>
                                     </div>
                                  </div>
