                          <div key={i} className="mb-4">
                             <h4 className="text-[10px] font-bold text-slate-500 mb-2 uppercase">{cat.category}</h4>
                             <div className="grid grid-cols-2 gap-2">
                               {cat.items.map(t => (
                                 <button
                                   key={t.id}
                                   onClick={() => updateCurrentSlideAnimation(t.id)}
