                    style={{ 
                      width: '1280px', 
                      height: '720px', 
                      transform: `scale(${scale})`,
                    }}
                    className={`shadow-2xl overflow-hidden bg-black rounded-lg ${!isPlaying ? 'ring-1 ring-white/10' : ''}`}
